window.QUIZ_BANK = {"version": "2d9619023cdddbd0", "questions": [{"id": "src-19f7f928932c-q001", "chapter": 3, "text": "Trong phương pháp sản xuất giá trị thặng dư tuyệt đối, giới hạn tối thiểu của ngày lao động là gì?", "options": [{"label": "A", "text": "Đủ bù đắp giá trị SLĐ của công nhân"}, {"label": "B", "text": "Lớn hơn thời gian lao động tất yếu"}, {"label": "C", "text": "Do nhà tư bản quy định"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "Nếu ngày lao động chỉ bằng thời gian tất yếu thì chỉ đủ bù giá trị sức lao động và không có thời gian thặng dư. Để tạo thặng dư, ngày lao động phải dài hơn thời gian tất yếu."}, {"id": "src-19f7f928932c-q002", "chapter": 3, "text": "Phương pháp sản xuất giá trị thặng dư tương đối thực hiện bằng cách nào?", "options": [{"label": "A", "text": "Thời gian lao động tất yếu và giá trị SLĐ thay đổi"}, {"label": "B", "text": "Hạ thấp giá trị SLĐ"}, {"label": "C", "text": "Rút ngắn thời gian lao động tất yếu trong điều kiện ngày lao động không đổi"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "D", "explanation": "Rút ngắn thời gian tất yếu làm thời gian thặng dư tăng trong ngày làm không đổi. Việc này gắn với giảm giá trị sức lao động qua năng suất xã hội. D được hiểu là tổng hợp A, B, C trong cùng hướng giảm; C là mô tả phương pháp rõ nhất."}, {"id": "src-19f7f928932c-q004", "chapter": 3, "text": "Điểm giống nhau giữa giá trị thặng dư tương đối và giá trị thặng dư siêu ngạch là gì?", "options": [{"label": "A", "text": "Tăng năng suất lao động ngành nông nghiệp"}, {"label": "B", "text": "Tăng năng suất lao động cá biệt"}, {"label": "C", "text": "Tăng năng suất lao động xã hội"}, {"label": "D", "text": "Tăng năng suất lao động"}], "answer": "D", "explanation": "Cả giá trị thặng dư tương đối và siêu ngạch đều gắn với tăng năng suất. Khác nhau ở phạm vi: tương đối dựa trên năng suất xã hội, còn siêu ngạch dựa trên ưu thế năng suất cá biệt."}, {"id": "src-19f7f928932c-q005", "chapter": 3, "text": "Sự khác nhau giữa giá trị thặng dư siêu ngạch và giá trị thặng dư tương đối thể hiện ở nội dung nào?", "options": [{"label": "A", "text": "Dựa vào tăng số lượng lao động"}, {"label": "B", "text": "Dựa trên cơ sở tăng năng suất lao động cá biệt"}, {"label": "C", "text": "Dựa trên cơ sở tăng cường độ lao động"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "Doanh nghiệp có giá trị cá biệt thấp hơn mức xã hội có thể thu phần thặng dư vượt trội khi bán theo điều kiện chung. Đó là cơ sở cá biệt của siêu ngạch, khác cơ chế tăng năng suất xã hội của tương đối."}, {"id": "src-19f7f928932c-q006", "chapter": 3, "text": "Giá trị thặng dư là gì?", "options": [{"label": "A", "text": "Lợi nhuận thu được của người sản xuất, kinh doanh"}, {"label": "B", "text": "Giá trị tư bản tăng lên"}, {"label": "C", "text": "Phần giá trị dôi ra ngoài giá trị SLĐ do công nhân làm ra"}, {"label": "D", "text": "Phần chênh lệch giữa giá trị hàng hóa với chi phí sản xuất TBCN"}], "answer": "C", "explanation": "Giá trị mới do lao động sống tạo ra gồm v+m. Phần vượt quá giá trị sức lao động v là m, tức giá trị thặng dư. Không nên đồng nhất m với mọi khoản chênh giá mua–bán."}, {"id": "src-19f7f928932c-q008", "chapter": 3, "text": "Căn cứ nào để phân chia Tư bản bất biến và Tư bản khả biến?", "options": [{"label": "A", "text": "Tốc độ chu chuyển của tư bản"}, {"label": "B", "text": "Vai trò của các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư"}, {"label": "C", "text": "Hao mòn hữu hình hoặc vô hình"}, {"label": "D", "text": "Phương thức chuyển giá trị các bộ phận tư bản sang sản phẩm"}], "answer": "B", "explanation": "Tiêu chí là vai trò của từng bộ phận trong tạo thặng dư: c chỉ chuyển giá trị đã có, còn sử dụng sức lao động mua bằng v tạo giá trị mới v+m. Cách chuyển giá trị theo chu kỳ là tiêu chí cố định/lưu động."}, {"id": "src-19f7f928932c-q009", "chapter": 3, "text": "Căn cứ nào để phân chia tư bản cố định và tư bản lưu động?", "options": [{"label": "A", "text": "Tốc độ chu chuyển của tư bản"}, {"label": "B", "text": "Phương thức chuyển giá trị các bộ phận tư bản sang sản phẩm"}, {"label": "C", "text": "Vai trò của các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư"}, {"label": "D", "text": "Sự thay đổi về lượng trong quá trình sản xuất"}], "answer": "B", "explanation": "Tư bản cố định và lưu động được phân biệt theo cách giá trị được chuyển vào sản phẩm. Cố định chuyển từng phần qua nhiều chu kỳ; lưu động được hoàn lại toàn bộ sau một vòng."}, {"id": "src-19f7f928932c-q010", "chapter": 3, "text": "Tư bản ứng trước bao gồm những đại lượng nào?", "options": [{"label": "A", "text": "Tư bản bất biến và Tư bản khả biến"}, {"label": "B", "text": "Tư bản bất biến, Tư bản khả biến và bộ phận tư bản tăng thêm trong quá tình sản xuất"}, {"label": "C", "text": "Bộ phận c1 và c2"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "Tư bản ứng trước K gồm phần mua tư liệu sản xuất c và phần mua sức lao động v. Giá trị thặng dư chưa được tạo ra lúc ứng vốn ban đầu nên không nằm trong K=c+v."}, {"id": "src-19f7f928932c-q011", "chapter": 3, "text": "Tư bản là gì?", "options": [{"label": "A", "text": "Tiền và máy móc thiết bị"}, {"label": "B", "text": "Tiền có khả năng sinh lời"}, {"label": "C", "text": "Công cụ sản xuất và nguyên vật liệu"}, {"label": "D", "text": "Giá trị mang lại giá trị thặng dư bằng cách bóc lột lao động làm thuê"}], "answer": "D", "explanation": "Tư bản không chỉ là một vật như tiền hoặc máy móc. Trong quan hệ sản xuất tư bản chủ nghĩa, nó là giá trị được ứng ra để thu thặng dư từ việc sử dụng lao động làm thuê."}, {"id": "src-19f7f928932c-q013", "chapter": 3, "text": "Hàng hóa SLĐ là gì?", "options": [{"label": "A", "text": "Tồn tại trong mọi nền sản xuất của xã hội"}, {"label": "B", "text": "Là loại hàng hóa đặc biệt có giá trị sử dụng có khả năng tạo ra giá trị mới trong quá trình sử dụng"}, {"label": "C", "text": "Chỉ có giá trị nhất định"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "Điểm đặc biệt của sức lao động là khi được sử dụng, nó có thể tạo ra lượng giá trị mới lớn hơn giá trị mua nó. Phần chênh lệch là cơ sở giải thích nguồn gốc giá trị thặng dư."}, {"id": "src-19f7f928932c-q014", "chapter": 3, "text": "TBBB và TBKB thuộc phạm trù tư bản nào?", "options": [{"label": "A", "text": "Sản xuất"}, {"label": "B", "text": "Tiền tệ"}, {"label": "C", "text": "Hàng hóa"}, {"label": "D", "text": "Lưu thông"}], "answer": "A", "explanation": "c và v là cách phân chia tư bản đang tham gia quá trình sản xuất theo vai trò trong tạo giá trị. Chúng không phải cách phân chia riêng của tư bản tiền tệ hoặc tư bản hàng hóa."}, {"id": "src-19f7f928932c-q015", "chapter": 3, "text": "Tỷ suất giá trị thặng dư phản ánh điều gì?", "options": [{"label": "A", "text": "Hiệu quả của tư bản"}, {"label": "B", "text": "Quy mô bóc lột của tư bản"}, {"label": "C", "text": "Trình độ bóc lột của tư bản đối với công nhân làm thuê"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "m′=m/v phản ánh phần thặng dư so với phần bù sức lao động, hay tỷ lệ thời gian thặng dư so với thời gian tất yếu. Nó đo trình độ khai thác lao động, không phải quy mô tuyệt đối của thặng dư."}, {"id": "src-19f7f928932c-q016", "chapter": 3, "text": "Để tăng khối lượng giá trị thặng dư có thể sử dụng cách thức nào?", "options": [{"label": "A", "text": "Tăng cường độ lao động khi ngày lao động không đổi"}, {"label": "B", "text": "Kéo dài thời gian lao động trong ngày"}, {"label": "C", "text": "Tăng năng suất lao động"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "D", "explanation": "Kéo dài ngày lao động hoặc tăng cường độ có thể làm tăng lao động thặng dư. Tăng năng suất trong điều kiện tạo thặng dư tương đối hoặc siêu ngạch cũng có thể làm tăng phần thặng dư. Vì thế đề chọn phương án tổng hợp; không phải mọi tăng năng suất đều tự làm tăng tổng giá trị."}, {"id": "src-19f7f928932c-q017", "chapter": 3, "text": "Khối lượng giá trị thặng dư phản ánh điều gì?", "options": [{"label": "A", "text": "Chỉ cho nhà tư bản biết nơi đầu tư có lợi"}, {"label": "B", "text": "Trình độ bóc lột giá trị thặng dự của nhà tư bản"}, {"label": "C", "text": "Quy mô bóc lột giá trị thặng dự của nhà tư bản"}, {"label": "D", "text": "Lượng lợi nhuận mà các nhà tư bản nhận được khi cạnh tranh tự do"}], "answer": "C", "explanation": "Khối lượng M là số giá trị thặng dư thu được, thường tính M=m′×V khi m′ viết dạng tỷ số. Nó biểu thị quy mô khai thác lao động, trong khi tỷ suất m′ biểu thị trình độ."}, {"id": "src-19f7f928932c-q018", "chapter": 3, "text": "Phương pháp sản xuất giá trị thặng dư tuyệt đối thực hiện bằng cách nào?", "options": [{"label": "A", "text": "Tiết kiệm chi phí sản xuất"}, {"label": "B", "text": "Sử dụng kỹ thuật tiên tiến, cải tiến tổ chức quản lý"}, {"label": "C", "text": "Kéo dài thời gian của ngày lao động, còn thời gian lao động tất yếu không đổi"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Giữ thời gian tất yếu không đổi nhưng kéo dài ngày làm thì phần thời gian thêm là thặng dư. Đây là phương pháp tuyệt đối, khác việc rút ngắn thời gian tất yếu của tương đối."}, {"id": "src-19f7f928932c-q019", "chapter": 3, "text": "Giá trị hàng hóa SLĐ gồm những giá trị nào?", "options": [{"label": "A", "text": "Chi phí đào tạo người lao động"}, {"label": "B", "text": "Giá trị các hàng hóa do người lao động tạo ra"}, {"label": "C", "text": "Chi phí sản xuất tư bản chủ nghĩa"}, {"label": "D", "text": "Cả ý a và c"}], "answer": "A", "explanation": "Chi phí đào tạo là một bộ phận của giá trị sức lao động. Các bộ phận khác còn gồm tư liệu sinh hoạt cần thiết cho người lao động và tái sản xuất thế hệ lao động; tổng giá trị hàng họ tạo ra không đồng nhất với giá trị sức lao động."}, {"id": "src-19f7f928932c-q020", "chapter": 3, "text": "Thực chất của quá trình tích lũy tư bản là gì?", "options": [{"label": "A", "text": "Tăng cấu tạo hữu cơ của tư bản"}, {"label": "B", "text": "Tăng quy mô của tư bản cá biệt bằng cách biến giá trị thặng dư thành tư bản"}, {"label": "C", "text": "Tăng năng suất lao động cá biệt"}, {"label": "D", "text": "Tăng năng suất lao động xã hội"}], "answer": "B", "explanation": "Tích lũy không chỉ là để dành tiền mà là chuyển một phần giá trị thặng dư thành tư bản phụ thêm để mở rộng sản xuất. Vì vậy đồng nhất tích lũy với tiết kiệm tư bản là không đúng."}, {"id": "src-19f7f928932c-q021", "chapter": 3, "text": "Phạm trù tỷ suất lợi nhuận cho biết điều gì?", "options": [{"label": "A", "text": "Trình độ kinh doanh của doanh nghiệp"}, {"label": "B", "text": "Mức độ hiệu quả của việc sử dụng lao động"}, {"label": "C", "text": "Khả năng bóc lột giá trị thặng dư của doanh nghiệp"}, {"label": "D", "text": "Khả năng sinh lời (mức doanh lợi) của việc đầu tư"}], "answer": "D", "explanation": "p′=p/K×100% cho biết mỗi đơn vị vốn ứng trước đem lại bao nhiêu lợi nhuận. Do đó nó phản ánh mức doanh lợi, không trực tiếp đo trình độ khai thác lao động như m′."}, {"id": "src-19f7f928932c-q022", "chapter": 3, "text": "Lợi nhuận bình quân hình thành trong điều kiện nào?", "options": [{"label": "A", "text": "Sản xuất hàng hóa"}, {"label": "B", "text": "Kinh tế thị trường"}, {"label": "C", "text": "Cạnh tranh tự do"}, {"label": "D", "text": "Phân công lao động"}], "answer": "C", "explanation": "Tự do cạnh tranh và khả năng chuyển vốn giữa ngành tạo xu hướng bình quân hóa tỷ suất lợi nhuận. Chỉ có sản xuất hàng hóa hoặc phân công lao động nói chung thì chưa đủ giải thích lợi nhuận bình quân."}, {"id": "src-19f7f928932c-q023", "chapter": 3, "text": "Bản chất của lợi nhuận thương nghiệp là gì?", "options": [{"label": "A", "text": "Lợi nhuận do kinh doanh hàng hóa mang lại"}, {"label": "B", "text": "Một phần của lợi nhuận bình quân do tư bản công nghiệp nhường cho tư bản thương nghiêp"}, {"label": "C", "text": "Lợi nhuận của tư bản hàng hóa"}, {"label": "D", "text": "Giá bán lẻ cao hơn giá bán buôn"}], "answer": "B", "explanation": "Thương nghiệp chuyên trách tiêu thụ hàng, nên tư bản sản xuất nhường lại cho nó một phần giá trị thặng dư để tạo lợi nhuận thương nghiệp. B là lựa chọn gần ý đó nhất; nguồn cuối cùng không phải do mua bán thuần túy tự tạo ra."}, {"id": "src-19f7f928932c-q024", "chapter": 3, "text": "Tỷ suất lợi nhuận bình quân hình thành do nguyên nhân nào?", "options": [{"label": "A", "text": "Tư bản có thể tự do di chuyển giữa các ngành"}, {"label": "B", "text": "Phân công lao động xã hội"}, {"label": "C", "text": "Hình thành độc quyền trong kinh tế"}, {"label": "D", "text": "Các nhà tư bản quy định"}], "answer": "A", "explanation": "Vốn dịch chuyển từ nơi lợi nhuận thấp sang nơi lợi nhuận cao, làm cung và tỷ suất các ngành biến đổi. Xu hướng đó hình thành tỷ suất lợi nhuận bình quân và lợi nhuận bình quân."}, {"id": "src-19f7f928932c-q025", "chapter": 3, "text": "Chi phí tư bản chủ nghĩa là gì?", "options": [{"label": "A", "text": "Chi phí lao động thực tế của xã hội để sản xuất ra hàng hóa"}, {"label": "B", "text": "Chi phí cho hoạt động kinh doanh hàng hóa"}, {"label": "C", "text": "Chi phí thuần túy về tư bản"}, {"label": "D", "text": "Chi phí chuyển nhượng thương hiệu"}], "answer": "C", "explanation": "Chi phí mà nhà tư bản bỏ ra gồm phần mua tư liệu sản xuất c và sức lao động v, nên k=c+v. Giá trị thặng dư m thuộc giá trị hàng hóa nhưng không phải khoản nhà tư bản trả cho lao động thặng dư."}, {"id": "src-19f7f928932c-q026", "chapter": 3, "text": "Quan hệ về lượng giữa lợi nhuận và giá trị thặng dư thể hiện ở nội dung nào?", "options": [{"label": "A", "text": "Lợi nhuận lớn hơn giá trị thặng dư"}, {"label": "B", "text": "Lợi nhuận nhỏ hơn giá trị thặng dư"}, {"label": "C", "text": "Lợi nhuận bằng giá trị thặng dư"}, {"label": "D", "text": "Lợi nhuận và giá trị thặng dư không đồng nhất về lượng nhưng tổng của lợi nhuận thì bằng tổng của giá trị thặng dư"}], "answer": "D", "explanation": "Lợi nhuận một doanh nghiệp có thể lệch giá trị thặng dư vì giá bán và phân phối giữa các ngành. Trong tổng thể xã hội theo mô hình lý luận, tổng lợi nhuận bằng tổng giá trị thặng dư."}, {"id": "src-19f7f928932c-q027", "chapter": 3, "text": "Tỷ suất lợi nhuận không phụ thuộc vào nhân tố nào?", "options": [{"label": "A", "text": "Tỷ suất giá trị thặng dư"}, {"label": "B", "text": "Tốc độ chu chuyển của tư bản"}, {"label": "C", "text": "Đại lượng tư bản ứng trước"}, {"label": "D", "text": "Hoạt động kinh doanh hàng hóa"}], "answer": "D", "explanation": "Các nhân tố trực tiếp thường xét gồm tỷ suất thặng dư, cấu tạo và quy mô vốn, chu chuyển và tiết kiệm c. D không phải tên một nhân tố xác định trong danh sách này; hiểu rộng thì hoạt động kinh doanh vẫn có thể tác động lợi nhuận nên câu hỏi cần đọc trong phạm vi phân loại của bài."}, {"id": "src-19f7f928932c-q028", "chapter": 3, "text": "Một tư bản cá biệt ứng trước 400.000 đơn vị tiền tệ (đvtt) để sản xuất hàng hóa với c/v = 4/1; m’ = 250%. Giá trị hàng hóa được tạo ra là bao nhiêu?", "options": [{"label": "A", "text": "320.000 đvtt"}, {"label": "B", "text": "280.000 đvtt"}, {"label": "C", "text": "200.000 đvtt"}, {"label": "D", "text": "600.000 đvtt"}], "answer": "D", "explanation": "K=400.000, c/v=4 nên v=400.000/5=80.000. m′=250% suy ra m=2,5×80.000=200.000. Với giả định toàn bộ c chuyển vào sản phẩm trong kỳ, W=K+m=600.000."}, {"id": "src-19f7f928932c-q029", "chapter": 3, "text": "Muốn tăng tỷ suất lợi nhuận thì chủ tư bản cần làm gì?", "options": [{"label": "A", "text": "Học tập để kinh doanh giỏi hơn"}, {"label": "B", "text": "Tăng tốc độ chu chuyển của tư bản"}, {"label": "C", "text": "Tăng quy mô tích lũy"}, {"label": "D", "text": "Tăng chi phí cho quảng cáo"}], "answer": "B", "explanation": "Chu chuyển nhanh hơn cho phép cùng lượng vốn vận động nhiều vòng trong năm, có thể tăng khối lượng thặng dư năm và tỷ suất lợi nhuận năm. Tăng chi phí quảng cáo hoặc quy mô tích lũy không tự bảo đảm tỷ suất tăng."}, {"id": "src-19f7f928932c-q030", "chapter": 3, "text": "Một doanh nghiệp tư bản năm thứ nhất ứng ra 500.000 £ để sản xuất hàng hóa, c/v = 4/1, m’ = 200%, cuối năm doanh nghiệp dành 50% khối lượng giá trị thặng dư đưa vào tích lũy. Lượng tư bản được tích lũy cuối năm thứ nhất của doanh nghiệp này là bao nhiêu?", "options": [{"label": "A", "text": "150.000£"}, {"label": "B", "text": "100.000£"}, {"label": "C", "text": "200.000£"}, {"label": "D", "text": "250.000£"}], "answer": "B", "explanation": "v=500.000/(4+1)=100.000; m=200%×100.000=200.000. Phần đưa vào tích lũy bằng 50%×200.000=100.000 £, không phải toàn bộ giá trị thặng dư."}, {"id": "src-19f7f928932c-q031", "chapter": 3, "text": "Hệ quả của tích lũy tư bản là gì?", "options": [{"label": "A", "text": "Chủ tư bản ít giá trị thặng dư hơn vì đã biến chúng thành tư bản"}, {"label": "B", "text": "Tăng quy mô của tư bản"}, {"label": "C", "text": "Tăng tốc độ chu chuyển của tư bản"}, {"label": "D", "text": "Tăng thời gian lưu thông"}], "answer": "B", "explanation": "Chuyển một phần thặng dư thành vốn phụ thêm làm lượng tư bản tăng và tạo điều kiện mở rộng sản xuất. Thời gian lưu thông hay tốc độ chu chuyển không nhất thiết thay đổi cùng chiều."}, {"id": "src-19f7f928932c-q032", "chapter": 3, "text": "Lợi nhuận bình quân là gì?", "options": [{"label": "A", "text": "Chênh lệch giữa chi phí sản xuất tư bản chủ nghĩa và giá trị hàng hóa"}, {"label": "B", "text": "Chênh lệch giữa tư bản sử dụng và tư bản đã tiêu dùng"}, {"label": "C", "text": "Lượng lợi nhuận bằng nhau của những tư bản như nhau đầu tư vào các ngành sản xuất khác nhau"}, {"label": "D", "text": "Lượng lợi nhuận mà tư bản công nghiệp nhường cho tư bản thương nghiệp"}], "answer": "C", "explanation": "Khi có tỷ suất lợi nhuận bình quân chung, lợi nhuận bình quân bằng tỷ suất đó nhân tư bản ứng trước. Vì vậy những lượng tư bản bằng nhau có lợi nhuận bình quân bằng nhau dù đầu tư khác ngành."}, {"id": "src-19f7f928932c-q033", "chapter": 3, "text": "Giả sử một doanh nghiệp có lượng tư bản ứng trước đầu năm là 780.000 đvtt, trong đó giá trị tư bản bất biến gấp 5 lần tư bản khả biến; tỷ suất giá trị thặng dư là 300%. Tỷ suất lợi nhuận mà doanh nghiệp này đạt được là bao nhiêu?", "options": [{"label": "A", "text": "40%"}, {"label": "B", "text": "45%"}, {"label": "C", "text": "50%"}, {"label": "D", "text": "60%"}], "answer": "C", "explanation": "c=5v và K=c+v=780.000 nên v=130.000. m=300%×130.000=390.000. p′=m/K×100%=390.000/780.000×100%=50%."}, {"id": "src-19f7f928932c-q035", "chapter": 3, "text": "Tư bản cố định và tư bản lưu động là bộ phận của tư bản nào?", "options": [{"label": "A", "text": "Tư bản tiền tệ"}, {"label": "B", "text": "Tư bản sản xuất"}, {"label": "C", "text": "Tư bản hàng hóa"}, {"label": "D", "text": "Tư bản cho vay"}], "answer": "B", "explanation": "Cố định và lưu động là hai bộ phận của tư bản sản xuất được phân theo cách chu chuyển giá trị. Tư bản tiền tệ và hàng hóa là các hình thái khác trong tuần hoàn."}, {"id": "src-19f7f928932c-q036", "chapter": 3, "text": "Một doanh nghiệp tư bản cá biệt ứng ra 900.000 đvtt để sản xuất hàng hóa với c/v = 8/1, m’ = 200%. Tỷ suất lợi nhuận mà doanh nghiệp này đạt được là bao nhiêu?", "options": [{"label": "A", "text": "18,3%"}, {"label": "B", "text": "20,5%"}, {"label": "C", "text": "22,2%"}, {"label": "D", "text": "25,2%"}], "answer": "C", "explanation": "v=900.000/(8+1)=100.000; m=200%×100.000=200.000. p′=200.000/900.000×100%=22,222…%, làm tròn là 22,2%."}, {"id": "src-19f7f928932c-q037", "chapter": 3, "text": "Tư bản lưu động bao gồm những giá trị nào?", "options": [{"label": "A", "text": "Máy móc, thiết bị, nhà xưởng"}, {"label": "B", "text": "Nguyên, nhiên vật liệu và sức lao động"}, {"label": "C", "text": "Chi phí cố định cho sản xuất"}, {"label": "D", "text": "Chi phí cho thuê mướn mặt bằng kinh doanh"}], "answer": "B", "explanation": "Vốn cho nguyên, nhiên vật liệu và mua sức lao động được hoàn lại toàn bộ sau mỗi vòng sản xuất. Lưu ý sức lao động tạo giá trị mới để bù v; không phải giá trị của nó được chuyển cơ học như nguyên liệu."}, {"id": "src-19f7f928932c-q038", "chapter": 3, "text": "Quy luật chung của tích lũy tư bản bao gồm nội dung nào?", "options": [{"label": "A", "text": "Tăng số lượng các nhà tư bản"}, {"label": "B", "text": "Tăng cường độ lao động"}, {"label": "C", "text": "Tăng chênh lệch thu nhập giữa nhà tư bản và công nhân làm thuê"}, {"label": "D", "text": "Tăng tỷ suất lợi nhuận"}], "answer": "C", "explanation": "Tích lũy làm tăng quy mô tư bản và trong mô hình lý luận làm tăng khoảng cách thu nhập giữa chủ tư bản và lao động làm thuê. Không thể suy rằng tích lũy luôn làm tăng tỷ suất lợi nhuận."}, {"id": "src-19f7f928932c-q039", "chapter": 3, "text": "Giả sử trong điều kiện cạnh tranh tự do, nền sản xuất xã hội gồm 3 ngành với cơ cấu tư bản đầu tư lần lượt là 2600C + 400V; 3500C + 500V; 2400C + 600V; m’ đều là 200%. Tỷ suất lợi nhuận bình quân được xác định là bao nhiêu?", "options": [{"label": "A", "text": "20%"}, {"label": "B", "text": "25%"}, {"label": "C", "text": "30%"}, {"label": "D", "text": "35%"}], "answer": "C", "explanation": "Vốn ba ngành là 3.000, 4.000 và 3.000, tổng 10.000. Với m′=200%, tổng m=2×(400+500+600)=3.000. Tỷ suất bình quân=3.000/10.000×100%=30%; không lấy trung bình cộng tỷ suất ba ngành."}, {"id": "src-811c9106b75b-q001", "chapter": 2, "text": "Theo góc độ nghiên cứu kinh tế chính trị, hàng hóa là gì?", "options": [{"label": "A", "text": "Sản phẩm của thị trường"}, {"label": "B", "text": "Sản phẩm của quá trình sản xuất"}, {"label": "C", "text": "Sản phẩm để thỏa mãn nhu cầu của con người"}, {"label": "D", "text": "Sản phẩm của lao động, có thể thỏa mãn nhu cầu nào đó của con người thông qua trao đổi, mua bán"}], "answer": "D", "explanation": "Một sản phẩm chỉ là hàng hóa khi do lao động tạo ra, có khả năng đáp ứng nhu cầu và được đưa ra trao đổi, mua bán. Chỉ có ích hoặc chỉ là sản phẩm lao động thì chưa đủ."}, {"id": "src-811c9106b75b-q002", "chapter": 2, "text": "Sản xuất hàng hóa tồn tại trong điều kiện nào?", "options": [{"label": "A", "text": "Mọi chế độ xã hội"}, {"label": "B", "text": "Trong các chế độ có tư hữu và có có tính chất tư nhân của sản xuất"}, {"label": "C", "text": "Trong xã hội có PCLĐ xã hội"}, {"label": "D", "text": "Trong xã hội có PCLĐ xã hội và có tính chất tư nhân của sản xuất"}], "answer": "D", "explanation": "Hai điều kiện phải cùng tồn tại là phân công lao động xã hội và sự tách biệt tương đối về kinh tế giữa những người sản xuất. Điều kiện thứ nhất tạo nhu cầu trao đổi; điều kiện thứ hai khiến sản phẩm phải được trao đổi dưới hình thức hàng hóa."}, {"id": "src-811c9106b75b-q003", "chapter": 2, "text": "Giá cả của hàng hóa là gì?", "options": [{"label": "A", "text": "Giá trị của hàng hóa"}, {"label": "B", "text": "Quan hệ về lượng giữa hàng hóa và tiền"}, {"label": "C", "text": "Tổng của chi phí sản xuất và lợi nhuận"}, {"label": "D", "text": "Biểu hiện bằng tiền của giá trị hàng hóa"}], "answer": "D", "explanation": "Trong lý luận giá trị, giá trị hàng hóa là cơ sở của giá cả. Giá thực tế còn chịu cung–cầu, cạnh tranh và sức mua của tiền, nên không phải lúc nào cũng bằng giá trị."}, {"id": "src-811c9106b75b-q006", "chapter": 2, "text": "Giá trị sử dụng của hàng hóa được tạo thành do lao động nào dưới đây ?", "options": [{"label": "A", "text": "Lao động trừu tượng"}, {"label": "B", "text": "Lao động giản đơn"}, {"label": "C", "text": "Lao động cụ thể"}, {"label": "D", "text": "Lao động phức tạp"}], "answer": "C", "explanation": "Lao động cụ thể có mục đích, đối tượng, công cụ và phương pháp riêng, nhờ đó tạo ra sản phẩm có công dụng xác định. Vì vậy nó tạo ra giá trị sử dụng."}, {"id": "src-811c9106b75b-q007", "chapter": 2, "text": "Giá trị hàng hóa được hình thành do lao động nào dưới đây?", "options": [{"label": "A", "text": "Lao động trừu tượng"}, {"label": "B", "text": "Lao động giản đơn"}, {"label": "C", "text": "Lao động cụ thể"}, {"label": "D", "text": "Lao động phức tạp"}], "answer": "A", "explanation": "Khi gạt bỏ hình thức nghề nghiệp cụ thể, lao động được xét như sự hao phí sức lao động nói chung. Mặt lao động trừu tượng này tạo ra giá trị của hàng hóa."}, {"id": "src-811c9106b75b-q008", "chapter": 2, "text": "Số lượng giá trị sử dụng của 1 hàng hóa có đặc điểm gì?", "options": [{"label": "A", "text": "Mỗi hàng hóa có duy nhất 1 giá trị sử dụng"}, {"label": "B", "text": "Mỗi hàng hóa có thể có nhiều hơn 1 giá trị sử dụng"}, {"label": "C", "text": "Hàng hóa có thể không có giá trị sử dụng"}, {"label": "D", "text": "Cả ý b và ý c đều đúng"}], "answer": "B", "explanation": "Một hàng hóa có thể thỏa mãn nhiều nhu cầu nhờ có nhiều thuộc tính hữu ích. Tuy nhiên nếu hoàn toàn không có giá trị sử dụng thì nó không thể là hàng hóa."}, {"id": "src-811c9106b75b-q009", "chapter": 2, "text": "Thị trường có vai trò như thế nào ?", "options": [{"label": "A", "text": "Thị trường là nơi sản xuất và cung ứng các hàng hóa, dịch vụ công cộng"}, {"label": "B", "text": "Thị trường đòi hỏi các chủ thể sản xuất cung cấp thông tin đầy đủ về sản phẩm của mình"}, {"label": "C", "text": "Thị trường là điều kiện, môi trường cho sản xuất phát triển"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Thị trường kết nối người mua và người bán, tạo đầu ra và tín hiệu để người sản xuất điều chỉnh hoạt động. Việc trực tiếp sản xuất dịch vụ công thuộc về các chủ thể, không phải bản thân thị trường."}, {"id": "src-811c9106b75b-q010", "chapter": 2, "text": "Điều kiện ra đời và tồn tại của sản xuất hàng hóa không bao gồm nội dung nào?", "options": [{"label": "A", "text": "Phân công lao động xã hội"}, {"label": "B", "text": "Sự tách biệt tương đối về kinh tế của những người sản xuất"}, {"label": "C", "text": "Yếu tố thị trường để tiêu thụ hàng hóa"}, {"label": "D", "text": "Tất cả các ý trên"}], "answer": "C", "explanation": "Hai điều kiện lý luận là phân công lao động xã hội và sự tách biệt tương đối về kinh tế của người sản xuất. “Yếu tố thị trường để tiêu thụ” không phải điều kiện độc lập trong cặp điều kiện đó."}, {"id": "src-811c9106b75b-q011", "chapter": 2, "text": "Lao động cụ thể là gì?", "options": [{"label": "A", "text": "Lao động mà ai cũng có thể làm được"}, {"label": "B", "text": "Lao động tạo ra giá trị của hàng hóa"}, {"label": "C", "text": "Lao động mà tập hợp của chúng tạo thành hệ thống PCLĐ xã hội"}, {"label": "D", "text": "Tất cả các ý trên"}], "answer": "C", "explanation": "Mỗi loại lao động cụ thể có nghề nghiệp và sản phẩm riêng; tổng thể các lao động ấy hình thành phân công lao động xã hội. Lao động cụ thể tạo giá trị sử dụng chứ không trực tiếp là mặt tạo giá trị."}, {"id": "src-811c9106b75b-q013", "chapter": 2, "text": "Lượng giá trị của 1 đơn vị hàng hóa thay đổi như thế nào ?", "options": [{"label": "A", "text": "Tăng khi năng suất lao động tăng"}, {"label": "B", "text": "Tăng khi năng suất lao động giảm"}, {"label": "C", "text": "Tăng khi trình độ lành nghề của người lao động tăng"}, {"label": "D", "text": "Tăng khi hiệu quả sử dụng tư liệu sản xuất tăng"}], "answer": "B", "explanation": "Năng suất giảm làm cần nhiều thời gian lao động xã hội hơn để tạo một đơn vị sản phẩm. Vì thế giá trị đơn vị tăng, nếu các điều kiện còn lại không đổi."}, {"id": "src-811c9106b75b-q015", "chapter": 2, "text": "Lao động giản đơn là loại lao động có đặc điểm gì ?", "options": [{"label": "A", "text": "Bất kỳ người lao động nào cũng có thể thực hiện"}, {"label": "B", "text": "Chỉ những người lao động đã qua đào tạo mới có thể thực hiện"}, {"label": "C", "text": "Chỉ những người lao động lành nghề mới có thể thực hiện được"}, {"label": "D", "text": "Trong một nghề nghiệp, chuyên môn nhất định"}], "answer": "A", "explanation": "Lao động giản đơn không đòi hỏi đào tạo chuyên môn đặc biệt và người lao động bình thường có thể thực hiện. Nó không có nghĩa mọi người đều có thể làm mọi công việc trong thực tế."}, {"id": "src-811c9106b75b-q016", "chapter": 2, "text": "Lao động phức tạp là loại lao động như thế nào ?", "options": [{"label": "A", "text": "Bất kỳ người lao động nào cũng có thể thực hiện"}, {"label": "B", "text": "Chỉ những người lao động đã qua đào tạo mới có thể thực hiện"}, {"label": "C", "text": "Có mục đích, đối tượng và phương thức và kết quả riêng"}, {"label": "D", "text": "Hao phí lao động nói chung của người lao động"}], "answer": "B", "explanation": "Lao động phức tạp đòi hỏi đào tạo, rèn luyện chuyên môn hoặc kỹ năng nhất định. Xét về tạo giá trị, nó được quy thành lao động giản đơn nhân lên."}, {"id": "src-811c9106b75b-q017", "chapter": 2, "text": "Đâu là thước đo lượng giá trị hàng hóa ?", "options": [{"label": "A", "text": "Thời gian lao động cá biệt"}, {"label": "B", "text": "Năng suất lao động"}, {"label": "C", "text": "Thời gian lao động xã hội cần thiết"}, {"label": "D", "text": "Giá trị xã hội của hàng hóa"}], "answer": "C", "explanation": "Trao đổi hàng hóa dựa trên mức hao phí mà xã hội thừa nhận, không dựa vào việc một người riêng lẻ làm nhanh hay chậm. Thước đo vì vậy là thời gian lao động xã hội cần thiết."}, {"id": "src-811c9106b75b-q018", "chapter": 2, "text": "Thuộc tính giá trị của hàng hóa có đặc điểm gì ?", "options": [{"label": "A", "text": "Giá trị hàng hóa là phạm trù vĩnh viễn"}, {"label": "B", "text": "Giá trị hàng hóa là phạm trù lịch sử"}, {"label": "C", "text": "Giá trị hàng hóa do giá trị trao đổi qui định"}, {"label": "D", "text": "Cả ý b và ý c đều đúng"}], "answer": "B", "explanation": "Giá trị gắn với sản xuất và trao đổi hàng hóa, không tồn tại vĩnh viễn trong mọi kiểu tổ chức sản xuất. Giá trị trao đổi là hình thức biểu hiện của giá trị, không phải yếu tố quyết định giá trị."}, {"id": "src-811c9106b75b-q019", "chapter": 2, "text": "Ai là chủ thể chính tham gia thị trường ?", "options": [{"label": "A", "text": "Nhà hoạch định chính sách"}, {"label": "B", "text": "Công an kinh tế"}, {"label": "C", "text": "Ngân hàng và các trung gian tài chính"}, {"label": "D", "text": "Nhà sản xuất"}], "answer": "D", "explanation": "Người sản xuất trực tiếp tạo ra và cung ứng hàng hóa, là một chủ thể cơ bản của thị trường. Các chủ thể khác có thể tham gia nhưng không thay thế vai trò này."}, {"id": "src-811c9106b75b-q020", "chapter": 2, "text": "Hàng hóa có mấy thuộc tính ?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "Không xác định"}], "answer": "A", "explanation": "Hàng hóa có hai thuộc tính: giá trị sử dụng và giá trị. Giá trị sử dụng nói đến công dụng; giá trị nói đến lao động xã hội kết tinh trong hàng hóa."}, {"id": "src-811c9106b75b-q021", "chapter": 2, "text": "Đâu là chức năng của tiền ?", "options": [{"label": "A", "text": "Đánh giá mức độ giàu có"}, {"label": "B", "text": "Thước đo mức độ tăng trưởng kinh tế của quốc gia"}, {"label": "C", "text": "Thước đo giá trị"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Thước đo giá trị là một chức năng của tiền: dùng tiền biểu hiện lượng giá trị và giá cả. Đánh giá mức giàu có hay tăng trưởng quốc gia không phải tên chức năng cơ bản của tiền trong câu hỏi."}, {"id": "src-811c9106b75b-q022", "chapter": 2, "text": "Giả có 3 cơ sở cùng sản xuất và cung ứng một loại hàng hóa X cho thị trường với thời gian lao động cá biệt (h/HH) và sản lượng hàng hóa X(HH) cung ứng như sau: Cơ sở A: 2h/HH  và cung ứng 250HH; Cơ sở B: 4h/HH và cung ứng 450HH; Cơ sở C: 1h/HH và cung ứng 100HH. TGLĐXHCT để sản xuất ra hàng hóa X là bao nhiêu ?", "options": [{"label": "A", "text": "2,75 h/HH"}, {"label": "B", "text": "3 h/HH"}, {"label": "C", "text": "3,25 h/HH"}, {"label": "D", "text": "3,75 h/HH"}], "answer": "B", "explanation": "Lấy tổng thời gian lao động chia tổng sản lượng: (2×250+4×450+1×100)/(250+450+100)=2.400/800=3 giờ/HH. Đây là cách tính bình quân gia quyền theo dữ kiện của bài, không phải bình quân cộng ba thời gian."}, {"id": "src-811c9106b75b-q023", "chapter": 2, "text": "Vì sao C.Mác nghiên cứu giá trị sử dụng của hàng hóa trước?", "options": [{"label": "A", "text": "Giá trị sử dụng là cái dễ thấy nhất của hàng hóa"}, {"label": "B", "text": "Giá trị sử dụng là biểu hiện ra ngoài của giá trị"}, {"label": "C", "text": "Giá trị sử dụng là cơ sở của giá trị trao đổi"}, {"label": "D", "text": "Giá trị sử dụng là cái mà cả người sản xuất và người tiêu dùng đều quan tâm"}], "answer": "A", "explanation": "Giá trị sử dụng thể hiện ở công dụng có thể nhận biết của vật, nên là điểm xuất phát trực quan trước khi phân tích giá trị. Nó là vật mang giá trị trao đổi chứ không phải lao động quyết định giá trị."}, {"id": "src-811c9106b75b-q024", "chapter": 2, "text": "Lao động cụ thể và lao động trừu tượng là các khái niệm dùng để chỉ nội dung nào của lao động sản xuất hàng hóa?", "options": [{"label": "A", "text": "Trình độ hay mức độ phức tạp của lao động sản xuất hàng hóa"}, {"label": "B", "text": "Tính chất hai mặt của lao động sản xuất hàng hóa"}, {"label": "C", "text": "Giá trị xã hội của lao động sản xuất hàng hóa"}, {"label": "D", "text": "Tính chất tư nhân hóa của lao động sản xuất hàng hóa"}], "answer": "B", "explanation": "Cùng một hoạt động sản xuất hàng hóa được xét dưới hai mặt: lao động cụ thể tạo giá trị sử dụng và lao động trừu tượng tạo giá trị. Đó là cơ sở của hai thuộc tính hàng hóa."}, {"id": "src-811c9106b75b-q026", "chapter": 2, "text": "Đâu là môt trong những đặc trưng cơ bản của kinh tế thị trường ?", "options": [{"label": "A", "text": "Nhà nước và thị trường cùng nhau giải quyết các quan hệ, hiện tượng kinh tế nảy sinh"}, {"label": "B", "text": "Nhà nước giữ vai trò chủ đạo trong nền kinh tế"}, {"label": "C", "text": "Động lực trực tiếp của chủ thể sản xuất kinh doanh là lợi ích kinh tế - xã hội"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "Nền kinh tế thị trường hiện đại kết hợp cơ chế thị trường với điều tiết của nhà nước. Động lực trực tiếp của chủ thể là lợi ích kinh tế; không thể suy từ đó rằng mọi nhà nước đều giữ vai trò chủ đạo như cách nói của phương án B."}, {"id": "src-811c9106b75b-q027", "chapter": 2, "text": "Khuyết tật của kinh tế thị trường là thể hiện ở nội dung nào ?", "options": [{"label": "A", "text": "Kinh tế thị trường là nền kinh tế mở, thị trường trong nước gắn liền với thị trường quốc tế"}, {"label": "B", "text": "Nền kinh tế thị trường luôn tiềm ẩn những rủi ro khủng hoảng"}, {"label": "C", "text": "Các chủ thể trong nền kinh tế thị trường luôn cạnh tranh với nhau"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "Các quyết định riêng lẻ và biến động cung–cầu có thể dẫn tới mất cân đối, khủng hoảng. Tính mở và cạnh tranh là đặc trưng của thị trường, không tự thân đồng nghĩa với khuyết tật được hỏi."}, {"id": "src-811c9106b75b-q028", "chapter": 2, "text": "Nguyên tắc ngang giá đòi hỏi các sản phẩm đem ra trao đổi trên thị trường phải đảm bảo điều kiện nào dưới đây ?", "options": [{"label": "A", "text": "Giá cả các hàng hóa bằng nhau"}, {"label": "B", "text": "Giá trị các hàng hóa bằng nhau"}, {"label": "C", "text": "Giá cả hàng hóa bằng giá trị hàng hóa"}, {"label": "D", "text": "Hao phí lao động cá biệt bằng hao phí lao động xã hội"}], "answer": "B", "explanation": "Trao đổi ngang giá đòi hỏi các lượng hàng đem trao đổi có giá trị tương đương. Đó không phải yêu cầu mọi món hàng có cùng giá tiền hoặc mọi người sản xuất có hao phí cá biệt bằng nhau."}, {"id": "src-811c9106b75b-q029", "chapter": 2, "text": "Quy luật giá trị có tác dụng gì ?", "options": [{"label": "A", "text": "Thúc đẩy cạnh tranh phát triển"}, {"label": "B", "text": "Thúc đẩy thị trường phát triển"}, {"label": "C", "text": "Kích thích cải tiến kỹ thuật, hợp lý hóa sản xuất"}, {"label": "D", "text": "Kích thích sản xuất và trao đổi hàng hóa"}], "answer": "C", "explanation": "Người hạ được hao phí cá biệt dưới mức xã hội sẽ có lợi thế. Áp lực đó thúc đẩy cải tiến kỹ thuật và hợp lý hóa sản xuất, là tác dụng trực tiếp và cụ thể được phương án C nêu."}, {"id": "src-811c9106b75b-q030", "chapter": 2, "text": "Tác dụng điều tiết sản xuất và lưu thông hàng hóa của qui luật giá trị thể hiện như thế nào ?", "options": [{"label": "A", "text": "Hàng hóa được vận chuyển từ nơi có giá cả thấp đến nơi có giá cả cao hơn"}, {"label": "B", "text": "Hình thành giá cả cân bằng trên thị trường"}, {"label": "C", "text": "Thúc đẩy năng lực thỏa mãn nhu cầu của xã hội"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "Trong lưu thông, người bán có động cơ đưa hàng từ nơi giá thấp sang nơi giá cao hơn. Dòng hàng này điều chỉnh phân bố hàng giữa các thị trường, thể hiện tác dụng điều tiết của quy luật giá trị."}, {"id": "src-811c9106b75b-q032", "chapter": 2, "text": "Đâu là cơ chế tác động của quy luật giá trị ?", "options": [{"label": "A", "text": "Khối lượng hàng hóa được giao dịch trên trị trường"}, {"label": "B", "text": "Lượng người bán và người mua"}, {"label": "C", "text": "Sự biến động của giá cả hàng hóa"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Giá trị không trực tiếp hiện thành con số quan sát trên thị trường. Sự lên xuống của giá cả quanh cơ sở giá trị cho thấy quy luật giá trị đang tác động tới lựa chọn của người sản xuất và trao đổi."}, {"id": "src-811c9106b75b-q033", "chapter": 2, "text": "Ưu thế của kinh tế thị trường thể hiện ở nội dung nào ?", "options": [{"label": "A", "text": "Minh bạch thông tin về sản phẩm"}, {"label": "B", "text": "Phân hóa xã hội"}, {"label": "C", "text": "Tạo ra các phương thức để thỏa mãn tối đa nhu cầu của con người"}, {"label": "D", "text": "Sự xuất hiện của độc quyền"}], "answer": "C", "explanation": "Cơ chế giá cả và cạnh tranh khuyến khích các chủ thể sử dụng nguồn lực vào nơi có lợi thế. Nhờ đó tiềm năng của doanh nghiệp, vùng và địa phương có điều kiện được phát huy."}, {"id": "src-811c9106b75b-q034", "chapter": 2, "text": "Các thuộc tính của hàng hóa có mối quan hệ với nhau như thế nào ?", "options": [{"label": "A", "text": "Thống nhất biện chứng với nhau"}, {"label": "B", "text": "Mâu thuẫn, bài trừ nhau"}, {"label": "C", "text": "Vừa thống nhất, vừa mâu thuẫn với nhau"}, {"label": "D", "text": "Độc lập, không có quan hệ với nhau"}], "answer": "C", "explanation": "Hai thuộc tính cùng tồn tại trong một hàng hóa nên thống nhất với nhau. Tuy nhiên người bán hướng tới thực hiện giá trị, người mua hướng tới giá trị sử dụng; hàng không bán được thì giá trị chưa được thực hiện, thể hiện mặt mâu thuẫn."}, {"id": "src-811c9106b75b-q035", "chapter": 2, "text": "Giá cả được hình thành một cách tự do là đặc trưng của cơ chế kinh tế nào ?", "options": [{"label": "A", "text": "Cơ chế kế hoạch hóa tập rung"}, {"label": "B", "text": "Cơ chế thị trường"}, {"label": "C", "text": "Cơ chế quản lý, điều tiết của nhà nước"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "Trong cơ chế thị trường, giá cả hình thành thông qua trao đổi, cạnh tranh và tương tác cung–cầu. Cơ chế kế hoạch hóa tập trung chủ yếu dựa vào quyết định và phân bổ hành chính."}, {"id": "src-811c9106b75b-q036", "chapter": 2, "text": "Vai trò cơ bản của người sản xuất trong nền kinh tế thị trường là gì ?", "options": [{"label": "A", "text": "Mua hàng hóa"}, {"label": "B", "text": "Quảng cáo sản phẩm"}, {"label": "C", "text": "Sản xuất và cung ứng hàng hóa"}, {"label": "D", "text": "Chỉ bán hàng hóa"}], "answer": "C", "explanation": "Người sản xuất kết hợp nguồn lực để tạo hàng hóa và đưa chúng ra thị trường. Quảng cáo hay bán hàng chỉ là một số hoạt động trong vai trò rộng hơn là sản xuất và cung ứng."}, {"id": "src-811c9106b75b-q037", "chapter": 2, "text": "Vai trò của nhà nước trong nền kinh tế thị trường là gì ?", "options": [{"label": "A", "text": "Quản lý nhà nước về kinh tế"}, {"label": "B", "text": "Thu thuế"}, {"label": "C", "text": "Không có vai trò gì cụ thể"}, {"label": "D", "text": "Chỉ sản xuất các sản phẩm công ích"}], "answer": "A", "explanation": "Nhà nước thiết lập và thực thi khuôn khổ quản lý kinh tế, đồng thời điều tiết và xử lý khuyết tật thị trường. Thu thuế hoặc cung cấp hàng công ích chỉ là những bộ phận của vai trò đó."}, {"id": "src-811c9106b75b-q038", "chapter": 2, "text": "Tác động điều tiết sản xuất của qui luật giá trị thể hiện ở nội dung nào ?", "options": [{"label": "A", "text": "Vận chuyển hàng hóa từ nơi có giá cả thấp đến nơi có giá cả cao hơn"}, {"label": "B", "text": "Thay đổi qui mô sản xuất và sản lượng hàng hóa"}, {"label": "C", "text": "Thiết lập nên khái niệ hàng tồn kho"}, {"label": "D", "text": "Điều chỉnh giá cả hàng hóa"}], "answer": "B", "explanation": "Khi giá cả và lợi ích thay đổi, nhà sản xuất mở rộng hoặc thu hẹp quy mô, kéo theo sản lượng thay đổi. Vận chuyển từ nơi giá thấp sang nơi giá cao là điều tiết lưu thông, không phải trực tiếp điều tiết sản xuất."}, {"id": "src-811c9106b75b-q039", "chapter": 2, "text": "Vì sao C.Mác bắt đầu nghiên cứu phương thức sản xuất TBCN từ hàng hóa?", "options": [{"label": "A", "text": "Hàng hóa là tế bào của kinh tế TBCN, chứa đựng những mầm mống mâu thuẫn của phương thức sản xuất TBCN"}, {"label": "B", "text": "Hàng hóa là hình thái biểu hiện phổ biến nhất của cải trong xã hội tư bản"}, {"label": "C", "text": "Hàng hóa là hình thái nguyên tố của của cải, phân tích hàng hóa là phân tích giá trị"}, {"label": "D", "text": "Tất cả các ý trên"}], "answer": "D", "explanation": "Hàng hóa vừa là hình thức phổ biến của của cải tư bản, vừa là đơn vị cơ bản chứa các quan hệ và mâu thuẫn cần phân tích. Ba nhận xét đều giải thích việc bắt đầu nghiên cứu từ hàng hóa."}, {"id": "src-811c9106b75b-q040", "chapter": 2, "text": "Thời gian lao động xã hội cần thiết không phụ thuộc vào nhân tố nào ?", "options": [{"label": "A", "text": "Năng suất lao động"}, {"label": "B", "text": "Cường độ lao động"}, {"label": "C", "text": "Qui mô sản xuất"}, {"label": "D", "text": "Trình độ lao động"}], "answer": "C", "explanation": "Định nghĩa thời gian cần thiết dùng điều kiện sản xuất bình thường, trình độ thành thạo và cường độ trung bình; năng suất quyết định thời gian cho một đơn vị. Quy mô riêng của một cơ sở không phải tiêu chí trực tiếp của định nghĩa đó."}, {"id": "src-811c9106b75b-q042", "chapter": 2, "text": "Đặc điểm cơ bản của thời gian lao động xã hội cần thiết là gì ?", "options": [{"label": "A", "text": "Gần sát với thời gian lao động cá biệt của người cung cấp nhiều hàng hóa nhất cho thị trường"}, {"label": "B", "text": "Là trung bình cộng của các thời gian lao động cá biệt"}, {"label": "C", "text": "Được xác định dựa trên lượng hàng hóa trên thị trường"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "Trong điều kiện thông thường, nhóm sản xuất theo điều kiện phổ biến và cung phần lớn sản lượng có ảnh hưởng chủ yếu tới mức xã hội. Vì vậy thời gian xã hội thường gần thời gian của nhóm ấy, không đơn giản là trung bình cộng mọi cơ sở."}, {"id": "src-811c9106b75b-q043", "chapter": 2, "text": "Vai trò của quy luật lưu thông tiền tệ thể hiện ở nội dung nào?", "options": [{"label": "A", "text": "Kiểm soát lạm phát"}, {"label": "B", "text": "Điều chỉnh hành vi của người mua và người bán"}, {"label": "C", "text": "Điều chỉnh dung lượng hàng hóa trên thị trường"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "Quy luật lưu thông tiền tệ giúp xác định lượng tiền phù hợp nhu cầu giao dịch. Vận dụng đúng giúp hạn chế tình trạng đưa tiền vượt yêu cầu lưu thông gây áp lực lạm phát."}, {"id": "src-811c9106b75b-q044", "chapter": 2, "text": "Mối quan hệ giữa giá cả hàng hóa và giá trị hàng hóa là gì?", "options": [{"label": "A", "text": "Giá cả quyết định giá trị"}, {"label": "B", "text": "Giá trị quyết định giá cả"}, {"label": "C", "text": "Độc lập với nhau"}, {"label": "D", "text": "Giá trị quyết định giá cả nhưng giá cả có tính độc lập tương đối"}], "answer": "D", "explanation": "Giá trị là cơ sở của giá cả, nhưng giá cả còn thay đổi theo cung–cầu, cạnh tranh và sức mua của tiền. Vì vậy phương án D đầy đủ hơn khẳng định giá trị quyết định giá cả mà không nêu tính độc lập tương đối."}, {"id": "src-811c9106b75b-q045", "chapter": 2, "text": "Thực chất chức năng phương tiện thanh toán của tiền là gì?", "options": [{"label": "A", "text": "Tiền là trung gian cho trao đổi hàng hóa"}, {"label": "B", "text": "Tiền tham gia trực tiếp vào giao dịch mua, bán hàng hóa"}, {"label": "C", "text": "Tiền dùng để chi trả các giao dịch trước hoặc sau khi mua, bán"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Phương tiện thanh toán dùng khi việc chi trả có thể tách thời điểm khỏi chuyển giao hàng hóa, như trả nợ hoặc ứng trước. Khác với phương tiện lưu thông, tiền không nhất thiết làm trung gian ngay tại lúc đổi hàng."}, {"id": "src-c1f911017e70-q001", "chapter": 1, "text": "Thuật ngữ Kinh tế chính trị xuất hiện lần đầu tiên vào năm nào?", "options": [{"label": "A", "text": "1818"}, {"label": "B", "text": "1883"}, {"label": "C", "text": "1615"}, {"label": "D", "text": "1895"}], "answer": "C", "explanation": "Thuật ngữ kinh tế chính trị được Antoine de Montchrétien dùng trong tác phẩm công bố năm 1615. Các mốc 1818, 1883 và 1895 không phải thời điểm xuất hiện thuật ngữ."}, {"id": "src-c1f911017e70-q002", "chapter": 1, "text": "Mục đích nghiên cứu của kinh tế chính trị là gì?", "options": [{"label": "A", "text": "Tìm ra các chính sách kinh tế"}, {"label": "B", "text": "Tìm ra các quy luật kinh tế cơ bản"}, {"label": "C", "text": "Tìm ra mối quan hệ giữa sản xuất và tiêu dùng"}, {"label": "D", "text": "Tìm ra mối quan hệ giữa hàng hóa và tiền tệ"}], "answer": "B", "explanation": "Mục đích nghiên cứu là nhận ra các quy luật chi phối sản xuất và trao đổi. Chính sách kinh tế là việc vận dụng nhận thức ấy vào hoàn cảnh cụ thể, không phải bản thân mục đích khoa học cơ bản."}, {"id": "src-c1f911017e70-q003", "chapter": 1, "text": "Kinh tế chính trị Mác – Lênin kế thừa trực tiếp những giá trị khoa học của trường phái kinh tế chính trị nào trong lịch sử?", "options": [{"label": "A", "text": "Chủ nghĩa trọng thương"}, {"label": "B", "text": "Kinh tế chính trị tiểu tư sản"}, {"label": "C", "text": "Kinh tế chính trị tư sản cổ điển Anh"}, {"label": "D", "text": "Kinh tế chính trị tầm thường"}], "answer": "C", "explanation": "Kinh tế chính trị tư sản cổ điển Anh, tiêu biểu là Adam Smith và David Ricardo, cung cấp những thành tựu lý luận về lao động và giá trị để Mác kế thừa, phê phán và phát triển."}, {"id": "src-c1f911017e70-q004", "chapter": 1, "text": "Kinh tế chính trị Mác – Lênin ra đời vào thời điểm nào?", "options": [{"label": "A", "text": "Cuối thế kỉ 18"}, {"label": "B", "text": "Những năm 40 của thế kỉ 19"}, {"label": "C", "text": "Cuối thể kỉ 19"}, {"label": "D", "text": "Đầu thế kỉ 20"}], "answer": "B", "explanation": "Những năm 1840 là giai đoạn Mác và Ăngghen hình thành nền tảng lý luận mới. Lênin về sau bảo vệ và phát triển học thuyết trong điều kiện lịch sử khác."}, {"id": "src-c1f911017e70-q005", "chapter": 1, "text": "Chức năng cơ bản của Kinh tế chính trị Mác – Lênin là gì?", "options": [{"label": "A", "text": "Tiêu chuẩn hành vi của các chủ thể kinh tế"}, {"label": "B", "text": "Nghiên cứu vai trò của các chủ thể kinh tế"}, {"label": "C", "text": "Chức năng thực tiễn"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Chức năng thực tiễn thể hiện ở việc dùng nhận thức quy luật để định hướng hoạt động kinh tế. Các chức năng còn thường được nêu là nhận thức, tư tưởng và phương pháp luận; A và B không phải tên các chức năng đó."}, {"id": "src-c1f911017e70-q006", "chapter": 1, "text": "Phương pháp nghiên cứu đặc thù của Kinh tế chính trị Mác – Lênin là phương pháp nào?", "options": [{"label": "A", "text": "Sơ đồ tư duy"}, {"label": "B", "text": "Thống kê toán"}, {"label": "C", "text": "Trừu tượng hóa khoa học"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Trừu tượng hóa khoa học gạt bỏ các yếu tố ngẫu nhiên, tạm thời để làm rõ quan hệ bản chất. Thống kê và mô hình có thể hỗ trợ nhưng không thay thế phương pháp đặc thù này."}, {"id": "src-c1f911017e70-q007", "chapter": 1, "text": "Ai là người sáng lập ra trường phái Kinh tế chính trị Mác – Lênin?", "options": [{"label": "A", "text": "Karl Marx"}, {"label": "B", "text": "Karl Marx và V.I. Lenin"}, {"label": "C", "text": "Karl Marx và Ph. Engels"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "Mác và Ăngghen đặt nền tảng học thuyết; Lênin kế thừa và phát triển. Vì câu hỏi hỏi người sáng lập, cặp Mác–Ăngghen là lựa chọn phù hợp."}, {"id": "src-c1f911017e70-q008", "chapter": 1, "text": "Đối tượng nghiên cứu của Kinh tế chính trị Mác – Lênin là gì?", "options": [{"label": "A", "text": "Thị trường và vai trò của các chủ thể tham gia thị trường tại các giai đoạn lịch sử nhất định"}, {"label": "B", "text": "Các yếu tố cơ bản của quá trình sản xuất"}, {"label": "C", "text": "Mối quan hệ giữa quan hệ sản xuất và lực lượng sản xuất trong các phương thức sản xuất khác nhau"}, {"label": "D", "text": "Các quan hệ của sản xuất và trao đổi trong mối liên hệ biện chứng với lực lượng sản xuất và kiến trúc thượng tầng tương ứng"}], "answer": "D", "explanation": "Đối tượng là quan hệ xã hội của sản xuất và trao đổi, được xét gắn với lực lượng sản xuất và kiến trúc thượng tầng tương ứng. Chỉ nghiên cứu yếu tố kỹ thuật hoặc riêng thị trường thì chưa bao quát đối tượng này."}, {"id": "src-c1f911017e70-q009", "chapter": 1, "text": "Ý nghĩa nghiên cứu của Kinh tế chính trị Mác – Lênin là gì?", "options": [{"label": "A", "text": "Hình thành thế giới quan và phương pháp luận khoa học cho các chủ thể"}, {"label": "B", "text": "Hình thành tư duy trừu tượng hóa khoa học cho các chủ thể"}, {"label": "C", "text": "Giúp chủ thể thể kinh tế hiểu bản chất các hiện tượng, quá trình kinh tế; nắm vững quy luật kinh tế"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "D", "explanation": "Việc nghiên cứu giúp nhận thức bản chất và quy luật kinh tế, đồng thời rèn tư duy trừu tượng và phương pháp luận khoa học. Do các ý cùng nói đến những tác dụng đó, lựa chọn tổng hợp phù hợp."}, {"id": "src-c1f911017e70-q010", "chapter": 1, "text": "Phương pháp trừu tượng hóa khoa học là cách thức thực hiện nghiên cứu bằng cách nào?", "options": [{"label": "A", "text": "Sử dụng đồ thị và các thuật toán"}, {"label": "B", "text": "Mô hình hóa các kết quả nghiên cứu bằng sơ đồ tư duy"}, {"label": "C", "text": "Gạt bỏ những yếu tố ngẫu nhiên, những hiện tượng tạm thời để thấy được bản chất bên trong"}, {"label": "D", "text": "Kết hợp logic và lịch sử để tiếp cận bản chất, các xu hướng và quy luật kinh tế"}], "answer": "C", "explanation": "Trừu tượng hóa khoa học tạm gạt các biểu hiện bề ngoài và yếu tố ngẫu nhiên để nhận diện thuộc tính bản chất. Dùng đồ thị hoặc kết hợp logic–lịch sử là phương pháp hỗ trợ khác, không phải định nghĩa trực tiếp của thao tác này."}, {"id": "src-ebbea014b34e-q001", "chapter": 3, "text": "Điều kiện để tiền biến thành tư bản là", "options": [{"label": "A", "text": "Phải tích lũy được một lượng tiền lớn, tiền không được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}, {"label": "B", "text": "Phải tích lũy được một lượng tiền lớn, tiền được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}, {"label": "C", "text": "Phải tích lũy được một lượng hàng hóa lớn, hàng hóa phải được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}, {"label": "D", "text": "Phải tích lũy được một lượng máy móc lớn, máy móc được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}], "answer": "B", "explanation": "Tiền chỉ vận động như tư bản khi được ứng ra nhằm thu về giá trị lớn hơn, tức có giá trị thặng dư. Tích trữ tiền đơn thuần không làm nó tự trở thành tư bản."}, {"id": "src-ebbea014b34e-q003", "chapter": 3, "text": "Điều kiện để sức lao đông trở thành hàng hóa là:", "options": [{"label": "A", "text": "Người lao động không được tự do, người lao động không có tư liệu sản xuất"}, {"label": "B", "text": "Người lao động được tự do thân thể, người lao động có tư liệu sản xuất (người lao động không có việc làm?)"}, {"label": "C", "text": "Người lao động được tự do thân thể, người lao động không có tư liệu sản xuất"}, {"label": "D", "text": "Người lao động phải được tự do, người lao động tự nguyện đi làm."}], "answer": "C", "explanation": "Người lao động phải tự do về thân thể để có quyền bán sức lao động, đồng thời không có đủ tư liệu sản xuất để tự tổ chức sản xuất. Hai điều kiện này giải thích vì sao sức lao động được đưa ra thị trường."}, {"id": "src-ebbea014b34e-q004", "chapter": 3, "text": "Khẳng định nào sau đây Không đúng về hàng hóa sức lao động?", "options": [{"label": "A", "text": "Mua bán chịu"}, {"label": "B", "text": "Giá cả bằng giá trị mới do sức lao động tạo ra"}, {"label": "C", "text": "Giá trị sử dụng quyết định Giá trị"}, {"label": "D", "text": "Hàng hóa sức lao động chỉ bán quyền sử dụng, chứ không bán quyền sở hữu"}], "answer": "B", "explanation": "Giá trị mới do lao động tạo ra gồm phần bù giá trị sức lao động và phần thặng dư. Vì vậy không thể đồng nhất giá cả sức lao động với toàn bộ giá trị mới. Lưu ý mệnh đề C cũng diễn đạt chưa chuẩn: giá trị sử dụng không trực tiếp quyết định giá trị."}, {"id": "src-ebbea014b34e-q005", "chapter": 3, "text": "Giá trị sức lao động được đo gián tiếp bằng", "options": [{"label": "A", "text": "Giá trị những tư liệu sản xuất để nuôi sống người lao động"}, {"label": "B", "text": "Giá trị sử dụng những tư liệu tiêu dùng để nuôi sống người lao động"}, {"label": "C", "text": "Giá trị những tư liệu tiêu dùng để nuôi sống nhà tư bản"}, {"label": "D", "text": "Giá trị những tư liệu tiêu dùng để nuôi sống người lao động"}], "answer": "D", "explanation": "Để tái tạo sức lao động, người lao động cần những tư liệu sinh hoạt nhất định. Giá trị sức lao động vì thế được đo gián tiếp qua giá trị tư liệu sinh hoạt cần thiết, có tính đến đào tạo và tái sản xuất thế hệ lao động."}, {"id": "src-ebbea014b34e-q006", "chapter": 3, "text": "Giá trị sử dụng của hàng hóa sức lao động, khi tiêu dùng sẽ tạo ra:", "options": [{"label": "A", "text": "Giá trị mới nhỏ hơn giá trị bản thân nó"}, {"label": "B", "text": "Giá trị mới bằng giá trị bản thân nó"}, {"label": "C", "text": "Giá trị mới lớn hơn giá trị bản thân nó"}, {"label": "D", "text": "Giá trị sử dụng mới lớn hơn giá trị sử dụng bản thân nó"}], "answer": "C", "explanation": "Điểm đặc biệt của sức lao động là khi được sử dụng, nó có thể tạo ra lượng giá trị mới lớn hơn giá trị mua nó. Phần chênh lệch là cơ sở giải thích nguồn gốc giá trị thặng dư."}, {"id": "src-ebbea014b34e-q007", "chapter": 3, "text": "Giá trị thặng dư là…", "options": [{"label": "A", "text": "Toàn bộ phần lao động của công nhân"}, {"label": "B", "text": "Lao động sáng tạo của công nhân"}, {"label": "C", "text": "Phần lao động được trả công của công nhân"}, {"label": "D", "text": "Phần lao động không công của công nhân"}], "answer": "D", "explanation": "Công nhân tạo ra một phần giá trị để bù giá trị sức lao động và phần còn lại thuộc về nhà tư bản. Cách nói “lao động không công” trong đáp án chỉ phần lao động thặng dư chưa được trả ngang giá."}, {"id": "src-ebbea014b34e-q008", "chapter": 3, "text": "Ngày lao động của công nhân gồm hai phần:", "options": [{"label": "A", "text": "Thời gian lao động giản đơn và thời gian phức tạp"}, {"label": "B", "text": "Thời gian lao động giản đơn và thời gian lao tất yếu (cần thiết)"}, {"label": "C", "text": "Thời gian lao động tất yếu và thời gian lao động thặng dư"}, {"label": "D", "text": "Thời gian lao động phức tạp và thời gian lao động thặng dư"}], "answer": "C", "explanation": "Thời gian tất yếu tạo lượng giá trị tương đương giá trị sức lao động; thời gian thặng dư tạo phần giá trị vượt ra ngoài mức đó. Cộng hai phần được ngày lao động."}, {"id": "src-ebbea014b34e-q009", "chapter": 3, "text": "Tư bản bất biến (c) là…", "options": [{"label": "A", "text": "Giá trị tư liệu sản xuất, giá trị của nó được tăng lên sau quá trình sản xuất"}, {"label": "B", "text": "Giá trị tư liệu sản xuất, giá trị của nó giảm đi sau quá trình sản xuất"}, {"label": "C", "text": "Giá trị tư liệu sản xuất, giá trị của nó không thay đổi sau quá trình sản xuất"}, {"label": "D", "text": "Giá trị tư liệu sản xuất, giá trị sử dụng của nó được bảo tồn và chuyển  vào sản phẩm"}], "answer": "C", "explanation": "Giá trị tư liệu sản xuất đã tiêu dùng được bảo tồn và chuyển vào sản phẩm, không tự tăng lên trong quá trình sản xuất. “Bất biến” nói về vai trò của bộ phận giá trị này, không có nghĩa máy móc không hao mòn."}, {"id": "src-ebbea014b34e-q010", "chapter": 3, "text": "Tư bản khả biến (v) là…", "options": [{"label": "A", "text": "Giá trị tư liệu sản xuất, giá trị của nó được tăng lên sau quá trình sản xuất"}, {"label": "B", "text": "Giá trị sức lao động, giá trị của nó tăng lên sau quá trình sản xuất"}, {"label": "C", "text": "Giá trị sức lao động, giá trị của nó không thay đổi sau quá trình sản xuất"}, {"label": "D", "text": "Giá trị sức lao động, giá trị của nó giảm đi sau quá trình sản xuất"}], "answer": "B", "explanation": "Tư bản khả biến được ứng ra để mua sức lao động. Việc sử dụng sức lao động tạo ra giá trị mới v+m, lớn hơn phần v ban đầu khi có giá trị thặng dư."}, {"id": "src-ebbea014b34e-q011", "chapter": 3, "text": "Căn cứ để phân chia tư bản bất biến và tư bản khả biến là:", "options": [{"label": "A", "text": "Căn cứ vào hai loại lao động là lao động cụ thể và lao động trừu tượng"}, {"label": "B", "text": "Căn cứ vào hai loại lao động là lao động giản đơn và lao động phức tạp"}, {"label": "C", "text": "Căn cứ vào tính chất hai mặt của lao động sản xuất hàng hóa"}, {"label": "D", "text": "Căn cứ vào vai trò của các bộ phận này trong quá trình sản xuất ra giá trị sử dụng"}], "answer": "C", "explanation": "Đáp án nguồn liên hệ việc phân chia với tính hai mặt của lao động: lao động cụ thể bảo tồn, chuyển giá trị c; lao động trừu tượng tạo giá trị mới v+m. Căn cứ trực tiếp cần nhớ là vai trò khác nhau của c và v trong tạo giá trị thặng dư."}, {"id": "src-ebbea014b34e-q012", "chapter": 3, "text": "Chọn câu Đúng? Tỷ suất giá trị thặng dư:", "options": [{"label": "A", "text": "Tỷ lệ thuận với tư bản bất biến"}, {"label": "B", "text": "Tỷ lệ nghịch với tư bản bất biến"}, {"label": "C", "text": "Tỷ lệ thuận với tư bản khả biến"}, {"label": "D", "text": "Tỷ lệ nghịch với tư bản khả biến"}], "answer": "D", "explanation": "m′=m/v×100%. Nếu giữ m không đổi, v tăng thì m′ giảm và ngược lại. Quan hệ tỷ lệ nghịch này cần điều kiện m không đổi, không phải khẳng định v giảm luôn làm m′ tăng trong mọi thực tế."}, {"id": "src-ebbea014b34e-q013", "chapter": 3, "text": "Chọn câu Đúng? Dưới chủ nghĩa tư bản, bản chất tiền công là…", "options": [{"label": "A", "text": "Sự trả công cho lao động"}, {"label": "B", "text": "Giá cả của hàng hóa sức lao động"}, {"label": "C", "text": "Giá trị của hàng hóa lao động"}, {"label": "D", "text": "Giá trị sử dụng của hàng hóa sức lao động"}], "answer": "B", "explanation": "Cái công nhân bán là quyền sử dụng sức lao động trong thời gian nhất định. Tiền công vì vậy là giá cả của sức lao động, dù bề ngoài dễ bị hiểu thành giá cả của toàn bộ lao động."}, {"id": "src-ebbea014b34e-q014", "chapter": 3, "text": "Chọn câu trả lời Đúng?", "options": [{"label": "A", "text": "Tư bản bất biến tạo ra giá trị thặng dư"}, {"label": "B", "text": "Tư bản khả biến tạo ra giá trị thặng dư"}, {"label": "C", "text": "Tư bản cố định tạo ra giá trị thặng dư"}, {"label": "D", "text": "Tư bản lưu động tạo ra giá trị thặng dư"}], "answer": "B", "explanation": "Bộ phận v mua sức lao động; lao động sống của công nhân tạo ra giá trị mới và giá trị thặng dư. Tư liệu sản xuất c chỉ chuyển giá trị đã có. Nói chặt chẽ, sức lao động tạo thặng dư, không phải bản thân tiền v tự sinh giá trị."}, {"id": "src-ebbea014b34e-q015", "chapter": 3, "text": "Tỷ suất giá trị thặng phản ánh:", "options": [{"label": "A", "text": "Quy mô bóc lột của nhà tư bản đối vơi công nhân làm thuê"}, {"label": "B", "text": "Trình độ bóc lột của nhà tư bản đối với công nhân làm thuê"}, {"label": "C", "text": "Năng lực sản xuất của nhà tư bản"}, {"label": "D", "text": "Chỉ cho nhà tư bản biết nơi đầu tư có lợi"}], "answer": "B", "explanation": "m′=m/v phản ánh phần thặng dư so với phần bù sức lao động, hay tỷ lệ thời gian thặng dư so với thời gian tất yếu. Nó đo trình độ khai thác lao động, không phải quy mô tuyệt đối của thặng dư."}, {"id": "src-ebbea014b34e-q016", "chapter": 3, "text": "Hiện nay thường áp dụng phổ biến phương pháp sản xuất giá trị thặng dư nào?", "options": [{"label": "A", "text": "Phương pháp sản xuất giá trị thặng dư tuyệt đối"}, {"label": "B", "text": "Phương pháp sản xuất giá trị thặng dư tương đối"}, {"label": "C", "text": "Phương pháp sản xuất giá trị thặng dư siêu ngạch"}, {"label": "D", "text": "Phương pháp sản xuất lợi nhuận"}], "answer": "B", "explanation": "Phương pháp tương đối tăng phần thời gian thặng dư bằng cách rút ngắn thời gian tất yếu nhờ tăng năng suất ở các ngành liên quan tới tư liệu sinh hoạt. Đáp án nguồn xem đây là phương pháp phổ biến trong sản xuất dựa trên cải tiến kỹ thuật."}, {"id": "src-ebbea014b34e-q017", "chapter": 3, "text": "Quá trình tích lũy tư bản làm…", "options": [{"label": "A", "text": "Cấu tạo hữu cơ của tư bản không đổi"}, {"label": "B", "text": "Giảm cấu tạo hữu cơ của tư bản"}, {"label": "C", "text": "Tăng cấu tạo hữu cơ của tư bản"}, {"label": "D", "text": "Tăng cấu tạo kỹ thuật của tư bản"}], "answer": "C", "explanation": "Tích lũy thường gắn với cơ giới hóa và tăng lượng tư liệu sản xuất trên mỗi lao động. Khi tỷ lệ giá trị phản ánh thay đổi kỹ thuật ấy, cấu tạo hữu cơ c/v có xu hướng tăng."}, {"id": "src-ebbea014b34e-q018", "chapter": 3, "text": "Thời gian chu chuyển của tư bản được xác định bằng:", "options": [{"label": "A", "text": "Thời gian sản xuất + thời gian dự trữ sản xuất"}, {"label": "B", "text": "Thời gian sản xuất + thời gian lưu thông"}, {"label": "C", "text": "Thời gian lưu thông + thời gian vận chuyển"}, {"label": "D", "text": "Thời gian lưu thông + thời gian dự trữ sản xuất"}], "answer": "B", "explanation": "Một vòng chu chuyển gồm giai đoạn tư bản nằm trong sản xuất và giai đoạn mua đầu vào, bán đầu ra trong lưu thông. Vì vậy thời gian chu chuyển bằng thời gian sản xuất cộng thời gian lưu thông."}, {"id": "src-ebbea014b34e-q019", "chapter": 3, "text": "Tư bản bất biến và tư bản khả biến thuộc phạm trù tư bản nào?", "options": [{"label": "A", "text": "Tư bản sản xuất"}, {"label": "B", "text": "Tư bản tiền tệ"}, {"label": "C", "text": "Tư bản hàng hóa"}, {"label": "D", "text": "Tư bản lưu thông"}], "answer": "A", "explanation": "c và v là cách phân chia tư bản đang tham gia quá trình sản xuất theo vai trò trong tạo giá trị. Chúng không phải cách phân chia riêng của tư bản tiền tệ hoặc tư bản hàng hóa."}, {"id": "src-ebbea014b34e-q020", "chapter": 3, "text": "Chọn ý Đúng về mua bán hàng hóa sức lao động", "options": [{"label": "A", "text": "Giá cả > giá trị do sức lao động tạo ra"}, {"label": "B", "text": "Mua, bán không có thời hạn"}, {"label": "C", "text": "Bán chịu"}, {"label": "D", "text": "Bán cả quyền sở hữu và quyền sử dụng"}], "answer": "C", "explanation": "Người lao động thường làm việc rồi mới nhận tiền công, nên giao dịch có tính bán chịu. Họ bán quyền sử dụng sức lao động có thời hạn, không bán quyền sở hữu bản thân."}, {"id": "src-ebbea014b34e-q021", "chapter": 3, "text": "Sản xuất giá trị thặng dư tuyệt đối và sản xuất giá trị thặng dư tương đối giống nhau cơ bản ở điểm nào?", "options": [{"label": "A", "text": "Đều làm tăng tỷ suất giá trị thặng dư"}, {"label": "B", "text": "Đều làm giảm giá trị sức lao động"}, {"label": "C", "text": "Đều làm giảm thời gian lao động tất yếu"}, {"label": "D", "text": "Đều làm tăng độ dài ngày lao động"}], "answer": "A", "explanation": "Cả hai phương pháp đều làm tỷ lệ thời gian thặng dư so với thời gian tất yếu tăng, tức m′ tăng. Tuyệt đối kéo dài ngày làm; tương đối rút ngắn thời gian tất yếu."}, {"id": "src-ebbea014b34e-q022", "chapter": 3, "text": "Sản xuất giá trị thặng dư tương đối và giá trị thặng dư siêu ngạch không giống nhau ở điểm nào?", "options": [{"label": "A", "text": "Dựa trên tăng năng suất lao động"}, {"label": "B", "text": "Dựa trên rút ngắn thời gian lao động cần thiết"}, {"label": "C", "text": "Dựa trên tăng năng suất lao động xã hội"}, {"label": "D", "text": "Làm cho m’ tăng"}], "answer": "C", "explanation": "Tương đối gắn với tăng năng suất xã hội làm giảm giá trị sức lao động. Siêu ngạch gắn với ưu thế năng suất cá biệt của một doanh nghiệp so với mức xã hội. Vì vậy “tăng năng suất xã hội” là điểm phân biệt được chọn."}, {"id": "src-ebbea014b34e-q023", "chapter": 3, "text": "Chọn ý Đúng:", "options": [{"label": "A", "text": "Tư bản bất biến là một bộ phận của tư bản cố định"}, {"label": "B", "text": "Tư bản cố định là một bộ phận của tư bản bất biến"}, {"label": "C", "text": "Tư bản lưu động là một bộ phận của tư bản khả biến"}, {"label": "D", "text": "Tư bản khả biến là một bộ phận của tư bản bất biến"}], "answer": "B", "explanation": "Tư bản cố định, như máy móc và nhà xưởng, thuộc tư liệu sản xuất nên nằm trong tư bản bất biến. Nhưng tư bản bất biến còn có nguyên vật liệu thuộc tư bản lưu động."}, {"id": "src-ebbea014b34e-q024", "chapter": 3, "text": "Mục đích trực tiếp của nền sản xuất TBCN là:", "options": [{"label": "A", "text": "Sản xuất ra ngày càng nhiều của cải vật chất"}, {"label": "B", "text": "Mở rộng phạm vi thống trị của quan hệ sản xuất TBCN"}, {"label": "C", "text": "Tạo ra ngày càng nhiều giá trị thặng dư"}, {"label": "D", "text": "Làm cho lao động ngày càng lệ thuộc vào tư bản"}], "answer": "C", "explanation": "Mục tiêu trực tiếp của nhà tư bản là làm giá trị ứng trước tăng lên thông qua thu giá trị thặng dư. Sản xuất nhiều hàng hóa là phương tiện để thực hiện mục tiêu ấy."}, {"id": "src-ebbea014b34e-q025", "chapter": 3, "text": "Chọn ý Đúng. Giá trị của tư liệu sản xuất đã tiêu dùng…", "options": [{"label": "A", "text": "Tham gia tạo thành giá trị mới của sản phẩm"}, {"label": "B", "text": "Tham gia tạo thành giá trị sức lao động"}, {"label": "C", "text": "Tham gia tạo thành giá trị của sản phẩm mới"}, {"label": "D", "text": "Không tham gia tạo thành giá trị sản phẩm mới"}], "answer": "C", "explanation": "Giá trị tư liệu sản xuất đã dùng chuyển vào giá trị sản phẩm mới dưới dạng c. Nó góp phần cấu thành toàn bộ giá trị c+v+m, nhưng không thuộc phần giá trị mới v+m do lao động sống tạo ra."}, {"id": "src-ebbea014b34e-q026", "chapter": 3, "text": "Muốn tăng khối lượng giá trị thặng dư, nhà tư bản có thể sử dụng cách nào trong các cách dưới đây?", "options": [{"label": "A", "text": "Giảm thời gian lao động trong ngày, khi thời gian lao động cần thiết không đổi"}, {"label": "B", "text": "Giảm cường độ lao động khi ngày lao động không đổi"}, {"label": "C", "text": "Tăng giá trị sức lao động khi ngày lao động không đổi"}, {"label": "D", "text": "Giảm giá trị sức lao động khi ngày lao động không đổi"}], "answer": "D", "explanation": "Khi ngày lao động không đổi, giá trị sức lao động giảm làm thời gian tất yếu giảm và thời gian thặng dư tăng. Với các điều kiện thích hợp, khối lượng thặng dư thu được tăng."}, {"id": "src-ebbea014b34e-q027", "chapter": 3, "text": "Chọn ý đúng? Vai trò của máy móc trọng việc tạo ra giá trị thặng dư:", "options": [{"label": "A", "text": "Máy móc là nguồn gốc của giá trị thặng dư"}, {"label": "B", "text": "Máy móc là tiền đề vật chất cho việc tạo ra giá trị thặng dư"}, {"label": "C", "text": "Máy móc và sức lao động đều tạo ra giá trị thặng dư"}, {"label": "D", "text": "Máy móc là yếu tố quyết định để tạo ra giá trị thặng dư"}], "answer": "B", "explanation": "Máy móc giúp tổ chức sản xuất và nâng năng suất, nhưng không tự tạo giá trị mới. Nguồn trực tiếp của giá trị thặng dư là lao động sống, còn máy móc là điều kiện vật chất."}, {"id": "src-ebbea014b34e-q028", "chapter": 3, "text": "Ý kiến nào dưới đây là Không đúng", "options": [{"label": "A", "text": "Tích lũy tư bản là biến một phần giá trị thặng dư thành tư bản"}, {"label": "B", "text": "Nguồn gốc của tích lũy tư bản là giá trị thặng dư"}, {"label": "C", "text": "Động cơ của tích lũy tư bản cũng là giá trị thặng dư"}, {"label": "D", "text": "Tích lũy cơ bản là sự tiết kiệm tư bản"}], "answer": "D", "explanation": "Tích lũy không chỉ là để dành tiền mà là chuyển một phần giá trị thặng dư thành tư bản phụ thêm để mở rộng sản xuất. Vì vậy đồng nhất tích lũy với tiết kiệm tư bản là không đúng."}, {"id": "src-ebbea014b34e-q029", "chapter": 3, "text": "Đâu là nguồn gốc của tích lũy tư bản:", "options": [{"label": "A", "text": "Tài sản thừa kế"}, {"label": "B", "text": "Của cải tiết kiệm của nhà tư bản"}, {"label": "C", "text": "Giá trị thặng dư"}, {"label": "D", "text": "Đi huy động từ các nhà tư bản khác"}], "answer": "C", "explanation": "Tích lũy diễn ra khi giá trị thặng dư đã thu được không dùng hết cho tiêu dùng cá nhân mà được tái đầu tư. Nguồn trực tiếp của phần tư bản tăng thêm do tích lũy là giá trị thặng dư."}, {"id": "src-ebbea014b34e-q030", "chapter": 3, "text": "Thời gian chu chuyển của tư bản gồm thời gian sản xuất và thời gian lưu thông. Thời gian sản xuất không gồm:", "options": [{"label": "A", "text": "Thời gian lao động"}, {"label": "B", "text": "Thời gian tiêu thụ hàng hóa"}, {"label": "C", "text": "Thời gian dự trữ sản xuất"}, {"label": "D", "text": "Thời gian gián đoạn lao động"}], "answer": "B", "explanation": "Tiêu thụ hàng hóa là bán sản phẩm nên thuộc thời gian lưu thông. Thời gian sản xuất gồm lao động, gián đoạn lao động và dự trữ sản xuất."}, {"id": "src-ebbea014b34e-q031", "chapter": 3, "text": "Cho tư bản đầu tư là 1000; cấu tạo hữu cơ của tư bản là 4/1, giá trị thặng dư m = 400. Xác định m'?", "options": [{"label": "A", "text": "100%"}, {"label": "B", "text": "150%"}, {"label": "C", "text": "200%"}, {"label": "D", "text": "250%"}], "answer": "C", "explanation": "K=c+v=1.000 và c/v=4 nên v=1.000/5=200. Khi m=400, m′=m/v×100%=400/200×100%=200%."}, {"id": "src-ebbea014b34e-q033", "chapter": 3, "text": "Giá trị sử dụng của hàng hóa sức lao động được coi là", "options": [{"label": "A", "text": "Chìa khóa để giải quyết mâu thuẫn giữa tư bản và tư bản"}, {"label": "B", "text": "Chìa khóa để giải quyết mâu thuẫn công thức chung của tư bản"}, {"label": "C", "text": "Chìa khóa để giải quyết mâu thuẫn giữa tư bản và lao động"}, {"label": "D", "text": "Chìa khóa để giải quyết mâu thuẫn của lưu thông hàng hóa"}], "answer": "B", "explanation": "Mua bán sức lao động theo giá trị vẫn có thể tạo thặng dư, vì giá trị sử dụng của sức lao động tạo giá trị mới lớn hơn giá trị của nó. Điều này giải thích sự tăng giá trị trong công thức T–H–T′ mà không phải giả định trao đổi gian lận."}, {"id": "src-ebbea014b34e-q034", "chapter": 3, "text": "Khẳng định nào sau đây Đúng?", "options": [{"label": "A", "text": "Giá trị thặng dư cũng là giá trị"}, {"label": "B", "text": "Giá trị thặng dư và giá trị cùng bản chất"}, {"label": "C", "text": "Giá trị thặng dư là giá trị mới do người công nhân tạo ra"}, {"label": "D", "text": "Giá trị thặng dư là phần lao động không công do công nhân làm ra"}], "answer": "A", "explanation": "Giá trị thặng dư là một phần giá trị mới do lao động trừu tượng tạo ra, nên trước hết nó cũng là giá trị. Đây là mệnh đề được nguồn chọn; các lựa chọn khác có cách nói rộng hoặc thiếu phân biệt giữa toàn bộ giá trị mới và phần thặng dư."}, {"id": "src-ebbea014b34e-q035", "chapter": 3, "text": "Khẳng định nào sau đây không đúng?", "options": [{"label": "A", "text": "Giá trị của tư liệu sản xuất tham gia tạo thành giá trị mới của sản phẩm"}, {"label": "B", "text": "Giá trị tư liệu sản xuất tham gia tạo thành giá trị của sản phẩm mới"}, {"label": "C", "text": "Giá trị của tư liệu sản xuất không tham gia tạo thành giá trị mới của sản phẩm"}, {"label": "D", "text": "Giá trị của tư liệu sản xuất được dịch chuyển sang giá trị của sản phẩm mới"}], "answer": "A", "explanation": "Tư liệu sản xuất chỉ chuyển giá trị đã có vào sản phẩm. Phần giá trị mới là v+m do lao động sống tạo ra, nên nói giá trị tư liệu sản xuất tham gia tạo thành giá trị mới là sai."}, {"id": "src-ebbea014b34e-q036", "chapter": 3, "text": "Chọn đáp án Không đúng", "options": [{"label": "A", "text": "Giá trị mới của sản phẩm = v + m"}, {"label": "B", "text": "Giá trị của sản phẩm mới = v + m"}, {"label": "C", "text": "Giá trị của tư liệu sản xuất = c"}, {"label": "D", "text": "Giá trị của sức lao động = v"}], "answer": "B", "explanation": "v+m là giá trị mới, còn giá trị toàn bộ sản phẩm mới là c+v+m. Đáp án B sai vì đã bỏ phần c được chuyển từ tư liệu sản xuất."}, {"id": "src-ebbea014b34e-q037", "chapter": 3, "text": "Chọn ý Không đúng:", "options": [{"label": "A", "text": "Giá trị thặng dư cũng là giá trị"}, {"label": "B", "text": "Giá trị thặng dư và giá trị giống nhau về chất, chỉ khác nhau về lượng trong một hàng hóa"}, {"label": "C", "text": "Giá trị thặng dư là lao động thặng dư kết tinh"}, {"label": "D", "text": "Giá trị thặng dư là tư liệu sản xuất kết tinh"}], "answer": "D", "explanation": "Giá trị thặng dư là phần lao động thặng dư được vật hóa thành giá trị. Tư liệu sản xuất chỉ mang giá trị quá khứ được chuyển vào sản phẩm, không phải bản thân nguồn tạo giá trị thặng dư."}, {"id": "src-ebbea014b34e-q038", "chapter": 3, "text": "Trong phương pháp sản xuất giá trị thặng dư tuyệt đối, người lao động muốn giảm thời gian lao động trong ngày, còn nhà tư bản lại muốn kéo dài thời gian lao động trong ngày. Giới hạn tối thiểu của ngày lao động là bao nhiêu?", "options": [{"label": "A", "text": "Đủ bù đắp giá trị sức lao động của công nhân"}, {"label": "B", "text": "Do nhà tư bản quy định"}, {"label": "C", "text": "Lớn hơn thời gian lao động cần thiết"}, {"label": "D", "text": "Bằng thời gian lao động cần thiết"}], "answer": "C", "explanation": "Nếu ngày lao động chỉ bằng thời gian tất yếu thì chỉ đủ bù giá trị sức lao động và không có thời gian thặng dư. Để tạo thặng dư, ngày lao động phải dài hơn thời gian tất yếu."}, {"id": "src-ebbea014b34e-q039", "chapter": 3, "text": "Nếu nhà tư bản trả công theo đúng giá trị sức lao động thì có bóc lột giá trị thặng dư không?", "options": [{"label": "A", "text": "Không"}, {"label": "B", "text": "Có"}, {"label": "C", "text": "Bị lỗ vốn"}, {"label": "D", "text": "Hòa vốn"}], "answer": "B", "explanation": "Trả đúng giá trị sức lao động không có nghĩa trả toàn bộ giá trị mới công nhân tạo ra. Công nhân có thể làm việc vượt thời gian tất yếu, tạo phần thặng dư thuộc về nhà tư bản."}, {"id": "src-ebbea014b34e-q040", "chapter": 3, "text": "Các yếu tố dưới đây, yếu tố nào không thuộc tư bản cố định:", "options": [{"label": "A", "text": "Nguyên vật liệu dùng cho sản xuất"}, {"label": "B", "text": "Các phương tiện vận tải"}, {"label": "C", "text": "Máy móc, thiết bị"}, {"label": "D", "text": "Đất đai làm mặt bằng sản xuất, nhà xưởng"}], "answer": "A", "explanation": "Nguyên vật liệu được tiêu dùng và chuyển toàn bộ giá trị vào sản phẩm trong một chu kỳ, nên thuộc tư bản lưu động. Máy móc và phương tiện lao động chuyển giá trị từng phần qua nhiều chu kỳ."}, {"id": "src-ebbea014b34e-q041", "chapter": 3, "text": "Các yếu tố dưới đây, yếu tố nào thuộc tư bản lưu động:", "options": [{"label": "A", "text": "Máy móc, nhà xưởng"}, {"label": "B", "text": "Đất đai làm mặt bằng sản xuất"}, {"label": "C", "text": "Tiền lương"}, {"label": "D", "text": "Các phương tiện vận tải"}], "answer": "C", "explanation": "Tiền lương là phần vốn ứng để mua sức lao động, được hoàn lại qua giá trị sản phẩm sau mỗi vòng sản xuất. Vì vậy phần vốn này thuộc tư bản lưu động."}, {"id": "src-ebbea014b34e-q042", "chapter": 3, "text": "Tổng giá cả sản xuất của 2 ngành A và B là 650. Tổng lợi nhuận của 2 ngành là 150. Xác định tỷ suất lợi nhuận bình quân?", "options": [{"label": "A", "text": "20%"}, {"label": "B", "text": "30%"}, {"label": "C", "text": "40%"}, {"label": "D", "text": "50%"}], "answer": "B", "explanation": "Tổng giá cả sản xuất bằng chi phí sản xuất cộng lợi nhuận: k=650−150=500. Với giả định vốn ứng trước bằng chi phí trong mô hình đề, tỷ suất bình quân=150/500×100%=30%."}, {"id": "src-f38c2c0ea236-q001", "chapter": 2, "text": "Sản xuất tự cung, tự cấp có đặc trưng cơ bản nào sau đây?", "options": [{"label": "A", "text": "Sản phẩm làm ra để thoả mãn nhu cầu trực tiếp của người sản xuất;"}, {"label": "B", "text": "Sản phẩm làm ra để thoả mãn nhu cầu người khác;"}, {"label": "C", "text": "Sản phẩm làm ra để bán;"}, {"label": "D", "text": "Sản phẩm làm ra để trao đổi với sản phẩm của người khác."}], "answer": "A", "explanation": "Trong sản xuất tự cung, tự cấp, người sản xuất làm ra sản phẩm để đáp ứng nhu cầu trực tiếp của mình hoặc gia đình. Làm ra sản phẩm nhằm trao đổi, mua bán là đặc trưng của sản xuất hàng hóa."}, {"id": "src-f38c2c0ea236-q002", "chapter": 2, "text": "Sản xuất tự cung, tự cấp và sản xuất hàng hoá giống nhau ở điểm nào sau đây?", "options": [{"label": "A", "text": "Sản phẩm làm ra để thoả mãn nhu cầu trực tiếp của người sản xuất;"}, {"label": "B", "text": "Sản phẩm làm ra để thoả mãn nhu cầu xã hội;"}, {"label": "C", "text": "Quá trình sản xuất là sự kết hợp 2 yếu tố là sức lao động và tư liệu sản xuất để tạo ra sản phẩm;"}, {"label": "D", "text": "Quá trình tái sản xuất bao gồm 4 khâu là sản xuất, phân phối, trao đổi và tiêu dùng."}], "answer": "C", "explanation": "Cả hai hình thức sản xuất đều cần kết hợp sức lao động với tư liệu sản xuất để tạo ra sản phẩm. Điểm khác nhau chủ yếu là mục đích sử dụng sản phẩm: tự tiêu dùng hay trao đổi, mua bán."}, {"id": "src-f38c2c0ea236-q003", "chapter": 2, "text": "Sản xuất hàng hoá ra đời khi và chỉ khi cùng đồng thời tồn tại mấy điều kiện?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "A", "explanation": "Hai điều kiện phải cùng tồn tại là phân công lao động xã hội và sự tách biệt tương đối về kinh tế giữa những người sản xuất. Điều kiện thứ nhất tạo nhu cầu trao đổi; điều kiện thứ hai khiến sản phẩm phải được trao đổi dưới hình thức hàng hóa."}, {"id": "src-f38c2c0ea236-q004", "chapter": 2, "text": "Theo quan điểm C. Mác, hàng hoá gì ?", "options": [{"label": "A", "text": "Là sản phẩm của lao động;"}, {"label": "B", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người;"}, {"label": "C", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người và đi vào tiêu dùng;"}, {"label": "D", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người thông qua trao đổi hay mua bán."}], "answer": "D", "explanation": "Một sản phẩm chỉ là hàng hóa khi do lao động tạo ra, có khả năng đáp ứng nhu cầu và được đưa ra trao đổi, mua bán. Chỉ có ích hoặc chỉ là sản phẩm lao động thì chưa đủ."}, {"id": "src-f38c2c0ea236-q005", "chapter": 2, "text": "Hàng hoá có mấy thuộc tính?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "A", "explanation": "Hàng hóa có hai thuộc tính: giá trị sử dụng và giá trị. Giá trị sử dụng nói đến công dụng; giá trị nói đến lao động xã hội kết tinh trong hàng hóa."}, {"id": "src-f38c2c0ea236-q006", "chapter": 2, "text": "Giá trị sử dụng của hàng hoá là gì?", "options": [{"label": "A", "text": "Là biểu hiện bằng tiền của giá trị;"}, {"label": "B", "text": "Là hao phí lao động của người sản xuất hàng hoá kết tinh trong hàng hoá;"}, {"label": "C", "text": "Là công dụng của vật có thể thoả mãn nhu cầu nào đó của con người;"}, {"label": "D", "text": "Là quan hệ về một tỷ lệ nhất định, mà một hàng hoá này có thể đổi được một số lượng nhất định hàng hoá kia."}], "answer": "C", "explanation": "Giá trị sử dụng là khả năng đáp ứng một nhu cầu thông qua công dụng của sản phẩm. Nó không phải giá tiền hay lượng lao động đã hao phí để làm ra sản phẩm."}, {"id": "src-f38c2c0ea236-q007", "chapter": 2, "text": "Giá trị hàng hoá là gì?", "options": [{"label": "A", "text": "Là chi phí phí lao động của người sản xuất"}, {"label": "B", "text": "Là hao phí lao động của người sản xuất hàng hoá kết tinh trong hàng hoá;"}, {"label": "C", "text": "Là công dụng của vật có thể thoả mãn nhu cầu nào đó của con người;"}, {"label": "D", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người;"}], "answer": "B", "explanation": "Giá trị thể hiện lượng lao động xã hội, trừu tượng kết tinh trong hàng hóa. Cần phân biệt giá trị với công dụng của hàng hóa và với giá cả là hình thức biểu hiện bằng tiền."}, {"id": "src-f38c2c0ea236-q008", "chapter": 2, "text": "Lao động cụ thể tạo ra thuộc tính nào của hàng hoá?", "options": [{"label": "A", "text": "Giá tri;"}, {"label": "B", "text": "Giá trị và giá trị sử dụng;"}, {"label": "C", "text": "Giá trị sử dụng;"}, {"label": "D", "text": "Giá trị trao đổi;"}], "answer": "C", "explanation": "Lao động cụ thể có mục đích, đối tượng, công cụ và phương pháp riêng, nhờ đó tạo ra sản phẩm có công dụng xác định. Vì vậy nó tạo ra giá trị sử dụng."}, {"id": "src-f38c2c0ea236-q009", "chapter": 2, "text": "Lao động trừu tượng tạo ra thuộc tính nào của hàng hoá?", "options": [{"label": "A", "text": "Giá tri;"}, {"label": "B", "text": "Giá trị và giá trị sử dụng;"}, {"label": "C", "text": "Giá trị sử dụng;"}, {"label": "D", "text": "Giá trị trao đổi."}], "answer": "A", "explanation": "Khi gạt bỏ hình thức nghề nghiệp cụ thể, lao động được xét như sự hao phí sức lao động nói chung. Mặt lao động trừu tượng này tạo ra giá trị của hàng hóa."}, {"id": "src-f38c2c0ea236-q010", "chapter": 2, "text": "Lượng giá trị hàng hoá được đo bằng thước đo nào sau đây?", "options": [{"label": "A", "text": "Thời gian lao động"}, {"label": "B", "text": "Thời gian lao động trong điều kiện xấu"}, {"label": "C", "text": "Thời gian lao động trong điều kiện tốt"}, {"label": "D", "text": "Thời gian lao động xã hội cần thiết."}], "answer": "D", "explanation": "Trao đổi hàng hóa dựa trên mức hao phí mà xã hội thừa nhận, không dựa vào việc một người riêng lẻ làm nhanh hay chậm. Thước đo vì vậy là thời gian lao động xã hội cần thiết."}, {"id": "src-f38c2c0ea236-q011", "chapter": 2, "text": "Có mấy cách tính lượng giá trị hàng hoá?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "A", "explanation": "Bộ đề quy ước đáp án là 2 cách. Tuy nhiên câu hỏi chưa nêu rõ hai cách nào trong bài giảng, nên không thể suy ra một phân loại duy nhất từ câu chữ này. Nguyên tắc cần nhớ là lượng giá trị được đo bằng thời gian lao động xã hội cần thiết."}, {"id": "src-f38c2c0ea236-q012", "chapter": 2, "text": "Theo C. Mác, có mấy nhân tố ảnh hưởng đến lượng giá trị hàng hoá?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "B", "explanation": "Theo cách phân nhóm ba nhân tố của bộ đề: năng suất lao động, cường độ lao động và mức độ phức tạp của lao động. Cần phân biệt tổng giá trị với giá trị một đơn vị: tăng cường độ làm tăng tổng sản phẩm và tổng giá trị, nhưng không tự làm đổi giá trị một đơn vị."}, {"id": "src-f38c2c0ea236-q013", "chapter": 2, "text": "Theo C. Mác, nhân tố nào sau đây ảnh hưởng đến lượng giá trị của hàng hoá?", "options": [{"label": "A", "text": "Thời gian lao động của người công nhân;"}, {"label": "B", "text": "Giá cả các yếu tố đầu vào của sản xuất;"}, {"label": "C", "text": "Lao động giản đơn và lao động phức tạp;"}, {"label": "D", "text": "Khoa học - công nghệ."}], "answer": "C", "explanation": "Lao động phức tạp được quy thành lao động giản đơn nhân lên. Do đó cùng một thời gian, lao động phức tạp có thể được tính là tạo ra lượng giá trị lớn hơn lao động giản đơn."}, {"id": "src-f38c2c0ea236-q014", "chapter": 2, "text": "Muốn tăng năng suất lao động, người ta thường áp dụng phương pháp nào sau đây?", "options": [{"label": "A", "text": "Tăng các yếu tố đầu vào của sản xuất;"}, {"label": "B", "text": "Đẩy mạnh ứng dụng các thành tựu khoa học – công nghệ;"}, {"label": "C", "text": "Tăng cường liên kết sản xuất;"}, {"label": "D", "text": "Tăng số lượng lao động."}], "answer": "B", "explanation": "Ứng dụng khoa học và công nghệ giúp tạo được nhiều sản phẩm hơn trong cùng thời gian hoặc giảm thời gian cần cho một sản phẩm. Tăng số lao động hoặc kéo dài lao động không tự đồng nghĩa với tăng năng suất."}, {"id": "src-f38c2c0ea236-q015", "chapter": 2, "text": "Tiền tệ ra đời trải qua mấy hình thái của giá trị?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "C", "explanation": "Bốn hình thái lần lượt là giản đơn hay ngẫu nhiên, đầy đủ hay mở rộng, chung và tiền tệ. Tiền tệ xuất hiện khi vai trò vật ngang giá chung được cố định vào một hàng hóa."}, {"id": "src-f38c2c0ea236-q016", "chapter": 2, "text": "Theo quan điểm của C. Mác, tiền tệ có mấy chức năng?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "D", "explanation": "Năm chức năng gồm thước đo giá trị, phương tiện lưu thông, phương tiện thanh toán, phương tiện cất trữ và tiền tệ thế giới. Các chức năng phản ánh những cách tiền tham gia các quan hệ trao đổi."}, {"id": "src-f38c2c0ea236-q017", "chapter": 2, "text": "Tiền là loại hàng hoá nào sau đây?", "options": [{"label": "A", "text": "Hàng hoá thông thường;"}, {"label": "B", "text": "Hàng hoá phức tạp;"}, {"label": "C", "text": "Hàng hoá đặc biệt;"}, {"label": "D", "text": "Hàng hoá bình thường được nhân cách hoá."}], "answer": "C", "explanation": "Tiền là hàng hóa đặc biệt vì được tách ra làm vật ngang giá chung. Nhờ đó các hàng hóa khác có thể biểu hiện giá trị và trao đổi thông qua tiền."}, {"id": "src-f38c2c0ea236-q018", "chapter": 2, "text": "Hàng hoá nào sau đây là hàng hoá vô hình?", "options": [{"label": "A", "text": "Xe máy trong đại lý bán;"}, {"label": "B", "text": "Cắt tóc trong tiệm;"}, {"label": "C", "text": "Rau, quả bán trong chợ;"}, {"label": "D", "text": "Quần áo bán tại cửa hàng"}], "answer": "B", "explanation": "Cắt tóc là dịch vụ: lợi ích được cung cấp qua hoạt động phục vụ, không phải một vật thể hữu hình được bàn giao như xe máy, rau quả hay quần áo. Vì thế đây là ví dụ về hàng hóa vô hình."}, {"id": "src-f38c2c0ea236-q019", "chapter": 2, "text": "Thị trường được phân làm mấy loại?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "C", "explanation": "Đáp án nguồn quy ước có 4 loại. Số loại thị trường phụ thuộc tiêu chí phân chia, chẳng hạn đối tượng giao dịch, phạm vi hoặc mức độ cạnh tranh; đề chưa nêu tiêu chí nên không thể khẳng định mọi cách phân loại đều có đúng 4 loại."}, {"id": "src-f38c2c0ea236-q020", "chapter": 2, "text": "Nền kinh tế thị trường có mấy đặc trưng cơ bản?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "C", "explanation": "Theo cách trình bày bốn nhóm đặc trưng của bộ đề: chủ thể đa dạng và tự chủ, thị trường phân bổ nguồn lực, giá cả và lợi ích kinh tế định hướng hoạt động, và nền kinh tế có tính mở. Cách gộp các đặc trưng có thể khác giữa bài giảng; số 4 ở đây theo tài liệu nguồn."}, {"id": "src-f38c2c0ea236-q021", "chapter": 2, "text": "Nội dung nào sau đây là ưu thế cơ bản của kinh tế thị trường?", "options": [{"label": "A", "text": "Tạo cơ hội cho con người phấn đấu vươn lên;"}, {"label": "B", "text": "Phát huy tốt nhất tiềm năng thế mạnh của mọi chủ thể kinh tế, các vùng, địa phương;"}, {"label": "C", "text": "Tạo điều kiện cho các chủ thể nâng cao năng lực cạnh tranh;"}, {"label": "D", "text": "Tạo điều kiện cho con người và xã hội phát triển toàn diện."}], "answer": "B", "explanation": "Cơ chế giá cả và cạnh tranh khuyến khích các chủ thể sử dụng nguồn lực vào nơi có lợi thế. Nhờ đó tiềm năng của doanh nghiệp, vùng và địa phương có điều kiện được phát huy."}, {"id": "src-f38c2c0ea236-q022", "chapter": 2, "text": "Nội dung nào sau đây là khuyết tật cơ bản của kinh tế thị trường?", "options": [{"label": "A", "text": "Gây ra các căn bệnh khủng hoảng, thất nghiệp, lạm phát…"}, {"label": "B", "text": "Gây ra tình trạng người bóc lột người;"}, {"label": "C", "text": "Phân chia xã hội thành các giai cấp;"}, {"label": "D", "text": "Kìm hãm tiến bộ khoa học – công nghệ."}], "answer": "A", "explanation": "Sản xuất vì lợi ích riêng không tự bảo đảm cân đối cho toàn xã hội. Biến động và mất cân đối có thể gây khủng hoảng, thất nghiệp, lạm phát; đây là những khuyết tật cần cơ chế điều tiết."}, {"id": "src-f38c2c0ea236-q023", "chapter": 2, "text": "Quy luật nào sau đây là quy luật kinh tế cơ bản của nền kinh tế thị trường?", "options": [{"label": "A", "text": "Quy luật giá cả độc quyền"}, {"label": "B", "text": "Quy luật cạnh tranh;"}, {"label": "C", "text": "Quy luật tích luỹ;"}, {"label": "D", "text": "Quy luật giá trị thặng dư"}], "answer": "B", "explanation": "Trong bốn phương án, cạnh tranh là quy luật vận động của kinh tế thị trường: các chủ thể ganh đua để có điều kiện sản xuất và tiêu thụ có lợi. Cần lưu ý kinh tế thị trường còn chịu quy luật giá trị, cung–cầu và lưu thông tiền tệ; không chỉ có cạnh tranh."}, {"id": "src-f38c2c0ea236-q024", "chapter": 2, "text": "Quy luật giá trị là quy luật kinh tế cơ bản của nền sản xuất nào sau đây?", "options": [{"label": "A", "text": "Sản xuất tự cung, tự cấp;"}, {"label": "B", "text": "Sản xuất hàng hoá giản đơn;"}, {"label": "C", "text": "Sản xuất hàng hoá Tư bản chủ nghĩa;"}, {"label": "D", "text": "Của mọi nền sản xuất."}], "answer": "B", "explanation": "Nguồn chọn sản xuất hàng hóa giản đơn. Ở hình thức này việc sản xuất, trao đổi dựa trên hao phí lao động xã hội cần thiết. Quy luật giá trị thực tế còn tác động trong sản xuất hàng hóa tư bản chủ nghĩa, nên không nên hiểu đáp án này là phạm vi áp dụng duy nhất."}, {"id": "src-f38c2c0ea236-q025", "chapter": 2, "text": "Theo C. Mác, nội dung nào đưới đây phản ánh chính xác mối quan hệ giữa giá trị và giá trị sử dụng?", "options": [{"label": "A", "text": "Có quan hệ thống nhất trong hàng hoá;"}, {"label": "B", "text": "Có quan hệ mâu thuẫn trong hàng hoá;"}, {"label": "C", "text": "Có quan hệ thống nhất và không mâu thuẫn trong hàng hoá;"}, {"label": "D", "text": "Có quan hệ vừa thống nhất, vừa mâu thuẫn trong hàng hoá."}], "answer": "D", "explanation": "Hai thuộc tính cùng tồn tại trong một hàng hóa nên thống nhất với nhau. Tuy nhiên người bán hướng tới thực hiện giá trị, người mua hướng tới giá trị sử dụng; hàng không bán được thì giá trị chưa được thực hiện, thể hiện mặt mâu thuẫn."}, {"id": "src-f38c2c0ea236-q026", "chapter": 2, "text": "Theo C. Mác, nội dung nào dưới đây phản ánh đúng mối quan hệ giữa giá trị và giá trị trao đổi?", "options": [{"label": "A", "text": "Giá trị là nội dung, giá trị trao đổi là hình thức biểu hiện của giá trị;"}, {"label": "B", "text": "Giá trị trao đổi là nội dung, còn giá trị là hình thức biểu hiện của giá trị trao đổi;"}, {"label": "C", "text": "Giá trị trao đổi quyết định giá trị;"}, {"label": "D", "text": "Giá trị trao đổi và giá trị có quan hệ tác động lẫn nhau."}], "answer": "A", "explanation": "Giá trị là nội dung lao động xã hội chứa trong hàng hóa. Giá trị trao đổi là tỷ lệ trao đổi với hàng hóa khác, qua đó nội dung ấy biểu hiện ra ngoài."}, {"id": "src-f38c2c0ea236-q027", "chapter": 2, "text": "Theo C. Mác giá trị hàng hoá được quyết định bởi nhân tố nào sau đây?", "options": [{"label": "A", "text": "Công dụng của hàng hoá;"}, {"label": "B", "text": "Sự khan hiếm của hàng hoá;"}, {"label": "C", "text": "Hao phí sức lao động của người sản xuất hàng hoá;"}, {"label": "D", "text": "Giá cả thị trường."}], "answer": "C", "explanation": "Cơ sở quyết định giá trị là lao động xã hội cần thiết để sản xuất hàng hóa. Công dụng tạo giá trị sử dụng; khan hiếm và cung–cầu có thể làm giá cả biến động nhưng không thay thế cơ sở giá trị trong lý luận này."}, {"id": "src-f38c2c0ea236-q028", "chapter": 2, "text": "Theo C. Mác, giá cả hàng hoá được quyết định bởi nhân tố nào sau đây?", "options": [{"label": "A", "text": "Giá trị hàng hoá;"}, {"label": "B", "text": "Giá trị sử dụng của hàng hoá;"}, {"label": "C", "text": "Tương quan cung cầu về hàng hoá trên thị trường;"}, {"label": "D", "text": "Ý muốn của người bán."}], "answer": "A", "explanation": "Trong lý luận giá trị, giá trị hàng hóa là cơ sở của giá cả. Giá thực tế còn chịu cung–cầu, cạnh tranh và sức mua của tiền, nên không phải lúc nào cũng bằng giá trị."}, {"id": "src-f38c2c0ea236-q029", "chapter": 2, "text": "Lượng giá trị một đơn vị hàng hoá thay đổi theo quan hệ nào sau đây?", "options": [{"label": "A", "text": "Tỷ lệ nghich với tăng năng suất lao động;"}, {"label": "B", "text": "Tỷ lệ thuận với tăng năng suất lao động;"}, {"label": "C", "text": "Tỷ lệ nghịch với tăng cường độ lao động;"}, {"label": "D", "text": "Tỷ lệ thuận với tăng cường độ lao động."}], "answer": "A", "explanation": "Năng suất xã hội tăng khiến thời gian cần cho một đơn vị sản phẩm giảm. Vì lượng giá trị đơn vị phụ thuộc thời gian này, nó biến đổi ngược chiều với năng suất."}, {"id": "src-f38c2c0ea236-q030", "chapter": 2, "text": "Khi tăng cường độ lao động, tổng sản phẩm sản xuất ra và giá trị một đơn vị hàng hoá thay đổi như thế nào?", "options": [{"label": "A", "text": "Tổng sản phẩm tăng, giá trị một đơn vị sản phẩm tăng;"}, {"label": "B", "text": "Tổng sản phẩm tăng, giá trị một đơn vị sản phẩm giảm;"}, {"label": "C", "text": "Tổng sản phẩm tăng, giá trị một đơn vị sản phẩm không đổi;"}, {"label": "D", "text": "Tổng sản phẩm không đổi, giá trị một đơn vị sản phẩm tăng."}], "answer": "C", "explanation": "Tăng cường độ làm hao phí nhiều lao động hơn trong cùng thời gian, nên sản lượng và tổng giá trị cùng tăng. Với các điều kiện khác không đổi, giá trị trên một đơn vị sản phẩm không đổi."}, {"id": "src-f38c2c0ea236-q031", "chapter": 2, "text": "Vì sao hàng hoá có 2 thuộc tính?", "options": [{"label": "A", "text": "Lao động sản xuất hàng hoá có tính chất 2 mặt;"}, {"label": "B", "text": "Lao động sản xuất hàng hoá tạo ra sản phẩm để bán, để trao đổi;"}, {"label": "C", "text": "Lao động sản xuất hàng hoá là lao động có ích để tạo sản phẩm thoả mãn nhu cầu con người;"}, {"label": "D", "text": "Lao động của người sản xuất hàng hoá vừa mang tính chất tư nhân, vừa mang tính chất xã hội."}], "answer": "A", "explanation": "Cùng một hoạt động sản xuất hàng hóa được xét dưới hai mặt: lao động cụ thể tạo giá trị sử dụng và lao động trừu tượng tạo giá trị. Đó là cơ sở của hai thuộc tính hàng hóa."}, {"id": "src-f38c2c0ea236-q032", "chapter": 2, "text": "Nội dung nào trong các nội dung sau đây tạo nên cuộc cách mạng trong Học thuyết giá trị của C. Mác?", "options": [{"label": "A", "text": "Hai thuộc tính của hàng hoá;"}, {"label": "B", "text": "Tính chất 2 mặt của lao động sản xuất hàng hoá;"}, {"label": "C", "text": "Lượng giá trị của hàng hoá;"}, {"label": "D", "text": "Quy luật giá trị."}], "answer": "B", "explanation": "Phát hiện tính hai mặt của lao động giải thích được vì sao một hàng hóa vừa có công dụng vừa có giá trị. Nó cũng giúp phân tích vai trò lao động sống và lao động quá khứ trong việc tạo giá trị."}, {"id": "src-f38c2c0ea236-q033", "chapter": 2, "text": "Thực hiện chức năng nào trong các chức năng sau đây, tiền vận động theo công thức H – T – H?", "options": [{"label": "A", "text": "Thước đo giá trị;"}, {"label": "B", "text": "Phương tiện lưu thông;"}, {"label": "C", "text": "Phương tiện thanh toán;"}, {"label": "D", "text": "Phương tiện cất trữ."}], "answer": "B", "explanation": "Trong H–T–H, bán hàng lấy tiền rồi dùng tiền mua hàng khác. Tiền làm trung gian cho quá trình trao đổi, tức thực hiện chức năng phương tiện lưu thông."}, {"id": "src-f38c2c0ea236-q034", "chapter": 2, "text": "Giữa lao động cụ thể và lao động trừu tượng có quan hệ như thế nào?", "options": [{"label": "A", "text": "Lao động trừu tượng là nội dung, lao động cụ thể là hình thức biểu hiện;"}, {"label": "B", "text": "Luôn thống nhất;"}, {"label": "C", "text": "Thống nhất và không có mâu thuẫn;"}, {"label": "D", "text": "Vừa thống nhất, vừa mâu thuẫn"}], "answer": "D", "explanation": "Đây là hai mặt của cùng hoạt động lao động nên thống nhất. Nhưng lao động tư nhân có thể không được xã hội thừa nhận khi sản phẩm không đáp ứng nhu cầu hoặc hao phí quá lớn, làm bộc lộ mâu thuẫn."}, {"id": "src-f38c2c0ea236-q035", "chapter": 2, "text": "Người ta nhận thức hoạt động của quy luật giá trị trên thị trường thông qua nhân tố nào sau đây?", "options": [{"label": "A", "text": "Giá trị trao đổi;"}, {"label": "B", "text": "Sự vận động của giá cả thị trường;"}, {"label": "C", "text": "Sự vận động của cung – cầu;"}, {"label": "D", "text": "Sự vận động của giá cả sản xuất."}], "answer": "B", "explanation": "Giá trị không trực tiếp hiện thành con số quan sát trên thị trường. Sự lên xuống của giá cả quanh cơ sở giá trị cho thấy quy luật giá trị đang tác động tới lựa chọn của người sản xuất và trao đổi."}, {"id": "src-f38c2c0ea236-q036", "chapter": 2, "text": "Phân hoá người sản xuất thành kẻ giàu, người nghèo tạo điều kiện cho sự ra đời của chủ nghĩa Tư Bản là tác dụng của quy luật nào trong các quy luật kinh tế sau đây?", "options": [{"label": "A", "text": "Quy luật cạnh tranh;"}, {"label": "B", "text": "Quy luật giá trị;"}, {"label": "C", "text": "Quy luật lưu thông tiền tệ;"}, {"label": "D", "text": "Quy luật cung – cầu;"}], "answer": "B", "explanation": "Người có hao phí cá biệt thấp hơn mức xã hội có lợi thế và dễ tích lũy của cải. Người có hao phí cao dễ thua lỗ hoặc phá sản. Sự phân hóa đó là một tác động của quy luật giá trị."}, {"id": "src-f38c2c0ea236-q037", "chapter": 2, "text": "Vì sao khi nghiên cứu sản xuất Tư bản chủ nghĩa, C. Mác bắt đầu từ nghiên cứu hàng hoá?", "options": [{"label": "A", "text": "Hàng hoá thoả mãn nhu cầu con người và đáp ứng sự phát triển xã hội;"}, {"label": "B", "text": "Hàng hoá là tế bào kinh tế của nền sản xuất TBCN;"}, {"label": "C", "text": "Hàng hoá là thước đo sự phát triển nền sản xuất TBCN;"}, {"label": "D", "text": "Hàng hoá là trung gian mà qua đó nhà tư bản bóc lột công nhân làm thuê để làm giàu."}], "answer": "B", "explanation": "Hàng hóa là đơn vị kinh tế cơ bản và hình thức phổ biến của của cải trong xã hội tư bản. Phân tích nó giúp tìm ra các quan hệ và mâu thuẫn để tiếp tục nghiên cứu phương thức sản xuất tư bản chủ nghĩa."}, {"id": "src-f38c2c0ea236-q038", "chapter": 2, "text": "Trong nền kinh tế thị trường, các chủ thể sản xuất – kinh doanh hay gây ô nhiễm môi trường. Nguyên nhân nào trong các nguyên nhân sau dẫn tới tình trạng đó?", "options": [{"label": "A", "text": "Chủ doanh nghiệp không nắm chắc quy định của pháp luật;"}, {"label": "B", "text": "Ý thức chấp hành kỷ luật lao động của công nhân không tốt;"}, {"label": "C", "text": "Chủ doanh nghiệp chạy theo lợi nhuận;"}, {"label": "D", "text": "Cơ quan chức năng của nhà nước làm công tác thực thi pháp luật trong việc bảo vệ môi trường chưa tốt."}], "answer": "C", "explanation": "Chạy theo lợi nhuận có thể khiến doanh nghiệp cắt giảm chi phí xử lý chất thải và đẩy thiệt hại ra môi trường. Đây là động cơ kinh tế của hành vi được hỏi, dù thực thi pháp luật và ý thức cũng có ảnh hưởng."}, {"id": "src-f38c2c0ea236-q039", "chapter": 2, "text": "Nền kinh tế lạm phát, biểu hiện ở chỉ số T > H; để cân bằng lượng tiền và hàng, nhà nước tiến hành điều tiết; biện pháp nào trong các biện pháp điều tiết sau mang lại sự cân bằng nhanh nhất?", "options": [{"label": "A", "text": "Giảm lượng tiền mặt trong lưu thông;"}, {"label": "B", "text": "Tăng sản xuất hàng hoá trong nước;"}, {"label": "C", "text": "Vừa tăng sản xuất hàng hoá trong nước vừa nhập khẩu hàng hoá để bù đắp thiếu hụt;"}, {"label": "D", "text": "Đồng thời giảm tiền mặt trong lưu thông và tăng cường sản xuất hàng hoá trong nước."}], "answer": "D", "explanation": "Trong mô hình đơn giản của đề, điều chỉnh đồng thời hai phía sẽ thu hẹp chênh lệch tiền–hàng: giảm tiền lưu thông và tăng hàng hóa. Đây là đáp án theo giả định bài học, không có nghĩa thực tế luôn có một biện pháp nhanh nhất trong mọi tình huống."}, {"id": "src-f38c2c0ea236-q040", "chapter": 2, "text": "Lý luận nào trong các lý luận sau đây là lý luận trung tâm trong lý luận giá trị của C. Mác?", "options": [{"label": "A", "text": "Hai thuộc tính của hàng hoá;"}, {"label": "B", "text": "Tính chất 2 mặt của lao động sản xuất hàng hoá;"}, {"label": "C", "text": "Lượng giá trị và các nhân tố ảnh hưởng đến lượng giá trị;"}, {"label": "D", "text": "Quy luật giá trị."}], "answer": "B", "explanation": "Tính hai mặt của lao động là mắt xích giải thích quan hệ giữa giá trị sử dụng và giá trị, đồng thời làm rõ cách giá trị được bảo tồn và tạo mới. Vì vậy bộ đề xem nội dung này là trung tâm lý luận giá trị."}, {"id": "src-fa343e9bc4b6-q001", "chapter": 3, "text": "Căn cứ để phân chia tư bản cố định và tư bản lưu động là:", "options": [{"label": "A", "text": "Căn cứ vào tính chất chuyển giá trị sử dụng của nó vào trong sản phẩm mới."}, {"label": "B", "text": "Căn cứ vào tính chất chuyển giá trị của nó vào trong sản phẩm mới."}, {"label": "C", "text": "Căn cứ vào tính chất chuyển giá trị của nó vào trong  sản phẩm cũ."}, {"label": "D", "text": "Căn cứ vào tính vào tính chất chuyển giá trị thặng dư của nó vào trong sản phẩm mới."}], "answer": "B", "explanation": "Tư bản cố định và lưu động được phân biệt theo cách giá trị được chuyển vào sản phẩm. Cố định chuyển từng phần qua nhiều chu kỳ; lưu động được hoàn lại toàn bộ sau một vòng."}, {"id": "src-fa343e9bc4b6-q002", "chapter": 3, "text": "Tính chất chuyển giá trị của tư bản cố định là:", "options": [{"label": "A", "text": "Chuyển giá trị ngay một lần vào trong sản phẩm mới."}, {"label": "B", "text": "Chuyển giá trị dần dần, từng phần một vào trong sản phẩm mới."}, {"label": "C", "text": "Chuyển giá trị sử dụng dần dần, từng phần một vào trong sản phẩm mới."}, {"label": "D", "text": "Chuyển giá trị dần dần, từng phần một vào trong sản phẩm cũ."}], "answer": "B", "explanation": "Máy móc, nhà xưởng được dùng nhiều lần nên không chuyển toàn bộ giá trị vào một lô sản phẩm. Giá trị được phân bổ từng phần theo hao mòn trong quá trình sử dụng."}, {"id": "src-fa343e9bc4b6-q003", "chapter": 3, "text": "Tính chất chuyển giả trị của tư bản lưu động là", "options": [{"label": "A", "text": "Chuyển giá trị dẫn từng phần vào trong sản phẩm mới sau quá trình sản xuất."}, {"label": "B", "text": "Chuyển giá trị sử dụng toàn bộ vào trong sản phẩm mới sau quá trình sản xuất."}, {"label": "C", "text": "Chuyến giá trị toàn bộ vào trong sản phẩm mới sau quá trình sản xuất"}, {"label": "D", "text": "Chuyển giá trị toàn bộ vào trong sản phẩm cũ sau quá trình sản xuất."}], "answer": "C", "explanation": "Nguyên vật liệu bị tiêu dùng trong một chu kỳ; phần vốn lưu động được hoàn lại toàn bộ sau vòng đó. Đây là điểm khác với giá trị tư bản cố định được chuyển dần."}, {"id": "src-fa343e9bc4b6-q004", "chapter": 3, "text": "Tư bản lưu động là bộ phận tư bản khi tham gia vào quá trình sản xuất:", "options": [{"label": "A", "text": "Giá trị của nó được chuyển dần vào sản phẩm mới bao gồm: nguyên nhân vật liệu và tiền công lao động"}, {"label": "B", "text": "Giá trị sử dụng của nó được chuyển ngay một lần vào sản phẩm mới, bao gồm: nguyên nhiên vật liệu và tiền công"}, {"label": "C", "text": "Giá trị của nó được chuyển ngay một lần vào sản phẩm cũ, bao gồm: nguyên nhiên vật liệu và tiền công lao động."}, {"label": "D", "text": "Giá trị của nó được chuyển ngay một lần vào sản phẩm mới, bao gồm: nguyên nhiên vật liệu và tiền công lao động"}], "answer": "D", "explanation": "Vốn cho nguyên, nhiên vật liệu và mua sức lao động được hoàn lại toàn bộ sau mỗi vòng sản xuất. Lưu ý sức lao động tạo giá trị mới để bù v; không phải giá trị của nó được chuyển cơ học như nguyên liệu."}, {"id": "src-fa343e9bc4b6-q005", "chapter": 3, "text": "Chu kỳ khủng hoảng kinh tế trong chủ nghĩa tư bản bao gồm:", "options": [{"label": "A", "text": "Khủng hoảng - suy giảm - phục hồi - hưng thịnh."}, {"label": "B", "text": "Khủng hoảng - tiêu điều - phục hồi - hưng thịnh."}, {"label": "C", "text": "Khủng hoảng - tiêu điều - suy giảm - hưng thịnh."}, {"label": "D", "text": "Suy giảm - tiêu điều - phục hồi - hưng thịnh."}], "answer": "B", "explanation": "Mô hình chu kỳ truyền thống gồm khủng hoảng, tiêu điều, phục hồi và hưng thịnh. Các giai đoạn mô tả sự suy giảm rồi khôi phục và mở rộng sản xuất."}, {"id": "src-fa343e9bc4b6-q006", "chapter": 3, "text": "Chi phí sản xuất tư bản chủ nghĩa (k):", "options": [{"label": "A", "text": "Bao gồm m và v (k = m+v)"}, {"label": "B", "text": "Bao gồm c và m (k=c+m)"}, {"label": "C", "text": "Bao gồm c và v (k =c+v)"}, {"label": "D", "text": "Bao gồm c, v và m(k=c+v+m)"}], "answer": "C", "explanation": "Chi phí mà nhà tư bản bỏ ra gồm phần mua tư liệu sản xuất c và sức lao động v, nên k=c+v. Giá trị thặng dư m thuộc giá trị hàng hóa nhưng không phải khoản nhà tư bản trả cho lao động thặng dư."}, {"id": "src-fa343e9bc4b6-q007", "chapter": 3, "text": "Về lượng, chi phí sản xuất tư bản chủ nghĩa (k)", "options": [{"label": "A", "text": "Bằng giá trị hàng hóa."}, {"label": "B", "text": "Lớn hơn giá trị hàng hóa."}, {"label": "C", "text": "Nhỏ hơn giá trị hàng hóa."}, {"label": "D", "text": "Nhỏ hơn giá trị thặng dư."}], "answer": "C", "explanation": "Giá trị hàng hóa là W=c+v+m, còn chi phí sản xuất k=c+v. Khi m>0 thì k<W; phần chênh lệch là giá trị thặng dư."}, {"id": "src-fa343e9bc4b6-q008", "chapter": 3, "text": "Về bản chất lợi nhuận và giá trị thặng dư đều là", "options": [{"label": "A", "text": "Lao động cụ thể của công nhân."}, {"label": "B", "text": "Lao động không công của công nhân"}, {"label": "C", "text": "Lao động trừu tượng của công nhân."}, {"label": "D", "text": "Lao động phức tạp của công nhân."}], "answer": "B", "explanation": "Lợi nhuận là hình thức biểu hiện chuyển hóa của giá trị thặng dư. Xét nguồn gốc, cả hai gắn với phần lao động thặng dư không được trả công của người lao động làm thuê."}, {"id": "src-fa343e9bc4b6-q009", "chapter": 3, "text": "Khi hàng hóa được bán đúng giá trị thì:", "options": [{"label": "A", "text": "Lợi nhuận lớn hơn giá trị thặng dư."}, {"label": "B", "text": "Lợi nhuận bằng giá trị thăng dư"}, {"label": "C", "text": "Lợi nhuận nhỏ hơn giá trị thặng dư."}, {"label": "D", "text": "Giá trị thặng dư nhỏ hơn lợi nhuận thương nghiệp."}], "answer": "B", "explanation": "Nếu bán đúng giá trị W=c+v+m thì lợi nhuận p=W−k=m. Bán lệch giá trị có thể khiến p của doanh nghiệp khác m."}, {"id": "src-fa343e9bc4b6-q010", "chapter": 3, "text": "Về lượng lợi nhuận (p), có thể:", "options": [{"label": "A", "text": "Bằng, hoặc thấp hơn lượng giá trị thặng dư."}, {"label": "B", "text": "Cao hơn hoặc thấp hơn lượng giá trị thặng dư."}, {"label": "C", "text": "Bằng, cao hơn hoặc thấp hơn lượng giá trị thặng dư."}, {"label": "D", "text": "Bằng, hoặc cao hơn lương giá trị thặng dư."}], "answer": "C", "explanation": "Lợi nhuận được tính bằng giá bán trừ chi phí. Giá bán có thể cao hơn, bằng hoặc thấp hơn giá trị, nên lợi nhuận cá biệt cũng có thể lớn hơn, bằng hoặc nhỏ hơn giá trị thặng dư."}, {"id": "src-fa343e9bc4b6-q011", "chapter": 3, "text": "Về lương tỷ suất lợi nhuận (p\")", "options": [{"label": "A", "text": "Luôn luôn nhỏ hơn giá trị thặng dư"}, {"label": "B", "text": "Luôn luôn lớn hơn tỷ suất giá trị thặng dư"}, {"label": "C", "text": "Luôn luôn bằng tỷ suất giá trị thặng dư."}, {"label": "D", "text": "Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư"}], "answer": "D", "explanation": "Trong giả định p=m và c>0, p′=m/(c+v) còn m′=m/v. Mẫu số c+v lớn hơn v nên p′<m′. Cần phân biệt hai tỷ suất với lượng giá trị thặng dư."}, {"id": "src-fa343e9bc4b6-q012", "chapter": 3, "text": "Tỷ suất lợi nhuận (p”) là:", "options": [{"label": "A", "text": "Tỷ lệ phần trăm giữa tổng giá trị thặng dư và toàn bộ tư bản khả biến."}, {"label": "B", "text": "Tỷ lệ phần trăm giữa tổng giá trị thặng dư và toàn bộ tư bản ứng trước."}, {"label": "C", "text": "Tỷ lệ phần trăm giữa tổng giá trị thặng dư và toàn bộ tư bản bất biến."}, {"label": "D", "text": "Tỷ lệ phần trăm giữa tổng giá trị và toàn bộ tư bản ứng trước."}], "answer": "B", "explanation": "Tỷ suất lợi nhuận so lượng lợi nhuận với toàn bộ tư bản ứng trước: p′=p/(c+v)×100%. Trong mô hình p=m, công thức được viết m/(c+v)×100%."}, {"id": "src-fa343e9bc4b6-q013", "chapter": 3, "text": "Cạnh tranh trong nội bộ ngành sẽ:", "options": [{"label": "A", "text": "Hình thành lợi nhuận bình quân."}, {"label": "B", "text": "Hình thành giá trị thị trường của hàng hóa."}, {"label": "C", "text": "Hình thành giá cả thị trường của hàng hóa."}, {"label": "D", "text": "Hình thành giá cả sản xuất."}], "answer": "B", "explanation": "Các doanh nghiệp cùng ngành có điều kiện và giá trị cá biệt khác nhau nhưng cùng bán trên thị trường ngành. Sự cạnh tranh đó dẫn đến hình thành mức giá trị thị trường được xã hội thừa nhận."}, {"id": "src-fa343e9bc4b6-q014", "chapter": 3, "text": "Cạnh tranh trong nội bộ ngành là:", "options": [{"label": "A", "text": "Sự cạnh tranh giữa các nhà sản xuất trong cùng một ngành, sản xuất ra cùng một loại hàng hóa."}, {"label": "B", "text": "Sự cạnh tranh giữa các nhà sản xuất trong cùng một ngành, sản xuất ra cùng các loại hàng hóa."}, {"label": "C", "text": "Sự cạnh tranh giữa các nhà sản xuất trong các ngành, sản xuất ra cùng một loại hàng hóa."}, {"label": "D", "text": "Sự cạnh tranh giữa các nhà sản"}], "answer": "A", "explanation": "Cạnh tranh nội bộ ngành diễn ra giữa những người sản xuất cùng một loại hàng hóa. Cạnh tranh giữa các ngành là quá trình tìm nơi đầu tư có tỷ suất sinh lời tốt hơn."}, {"id": "src-fa343e9bc4b6-q015", "chapter": 3, "text": "Mục đích của cạnh tranh trong nội bộ ngành là:", "options": [{"label": "A", "text": "Tìm kiếm lợi nhuận."}, {"label": "B", "text": "Tìm kiếm lợi nhuận siêu ngạch."}, {"label": "C", "text": "Tìm kiếm lợi nhuận bình quân."}, {"label": "D", "text": "Tìm kiếm giá trị siêu ngạch."}], "answer": "B", "explanation": "Doanh nghiệp tìm cách hạ giá trị cá biệt dưới mức xã hội trong khi bán theo điều kiện thị trường chung. Phần lợi nhuận vượt mức thông thường là lợi nhuận siêu ngạch."}, {"id": "src-fa343e9bc4b6-q016", "chapter": 3, "text": "Cạnh tranh giữa các ngành là:", "options": [{"label": "A", "text": "Sự cạnh tranh giữa các nhà sản xuất trong cùng ngành."}, {"label": "B", "text": "Sự cạnh tranh giữa các nhà sản xuất ở các ngành khác nhau."}, {"label": "C", "text": "Sự cạnh tranh giữa các nhà sản xuất ở các nước khác nhau."}, {"label": "D", "text": "Sự cạnh tranh giữa các nhà tư bản ở các nước khác nhau."}], "answer": "B", "explanation": "Đây là cạnh tranh giữa các nhà tư bản đầu tư ở những ngành khác nhau. Họ so sánh mức sinh lời và có thể chuyển vốn từ ngành này sang ngành khác."}, {"id": "src-fa343e9bc4b6-q017", "chapter": 3, "text": "Mục đích của cạnh tranh giữa các ngành là:", "options": [{"label": "A", "text": "Nhằm tìm kiếm ngành đầu tư có giá trị cao."}, {"label": "B", "text": "Nhằm tìm kiếm ngành đầu tư có lợi nhuận cao."}, {"label": "C", "text": "Nhằm tìm kiếm ngành đầu tư có giá trị sử dụng cao."}, {"label": "D", "text": "Nhằm tìm kiếm ngành đầu tư có giá cả cao."}], "answer": "B", "explanation": "Động lực chuyển vốn là thu được tỷ suất lợi nhuận cao hơn. Ngành có hàng giá cao hoặc giá trị sử dụng cao chưa chắc có mức sinh lời trên vốn cao hơn."}, {"id": "src-fa343e9bc4b6-q018", "chapter": 3, "text": "Kết quả cạnh tranh giữa các ngành:", "options": [{"label": "A", "text": "Hình thành giá cả sản xuất."}, {"label": "B", "text": "Hình thành giá trị thị trường."}, {"label": "C", "text": "Hình thành lợi nhuận bình quân."}, {"label": "D", "text": "Hình thành chi phí sản xuất."}], "answer": "C", "explanation": "Vốn dịch chuyển từ nơi lợi nhuận thấp sang nơi lợi nhuận cao, làm cung và tỷ suất các ngành biến đổi. Xu hướng đó hình thành tỷ suất lợi nhuận bình quân và lợi nhuận bình quân."}, {"id": "src-fa343e9bc4b6-q019", "chapter": 3, "text": "Lợi nhuận bình quân là:", "options": [{"label": "A", "text": "Lợi nhuận không bằng nhau của những lượng vốn tư bản đầu tư bằng nhau khi đầu tư vào các ngành khác nhau."}, {"label": "B", "text": "Lợi nhuận bằng nhau của những lượng vốn tư bản đầu tư không bằng nhau khi đầu tư vào các ngành khác nhau"}, {"label": "C", "text": "Lợi nhuận bằng nhau của những lượng vốn tư bản đầu tư bằng nhau khi đầu tư vào các ngành khác nhau."}, {"label": "D", "text": "Lợi nhuận khác nhau của những lượng vốn tư bản đầu tư khác nhau khi đầu tư vào các ngành khác nhau."}], "answer": "C", "explanation": "Khi có tỷ suất lợi nhuận bình quân chung, lợi nhuận bình quân bằng tỷ suất đó nhân tư bản ứng trước. Vì vậy những lượng tư bản bằng nhau có lợi nhuận bình quân bằng nhau dù đầu tư khác ngành."}, {"id": "src-fa343e9bc4b6-q020", "chapter": 3, "text": "Tỷ suất lợi nhuận bình quân là:", "options": [{"label": "A", "text": "Tỷ suất lợi nhuận trung bình trong cùng một ngành."}, {"label": "B", "text": "Tỷ suất lợi nhuận trung bình giữa các ngành."}, {"label": "C", "text": "Tỷ suất lợi nhuận cao giữa các ngành."}, {"label": "D", "text": "Tỷ suất lợi nhuận độc quyền giữa các ngành."}], "answer": "B", "explanation": "Đây là tỷ suất chung giữa các ngành, được tính theo tổng thặng dư chia tổng tư bản ứng trước. Nó không phải trung bình cộng giản đơn nếu quy mô vốn các ngành khác nhau."}, {"id": "src-fa343e9bc4b6-q021", "chapter": 3, "text": "Khi hình thành lợi nhuận bình quân giá trị hàng hóa sẽ chuyển thành:", "options": [{"label": "A", "text": "Giá trị thị trường."}, {"label": "B", "text": "Chi phí sản xuất."}, {"label": "C", "text": "Giá cả sản xuất."}, {"label": "D", "text": "Giá cả thị trường."}], "answer": "C", "explanation": "Khi lợi nhuận được phân phối theo tỷ suất bình quân, giá bán làm cơ sở là chi phí cộng lợi nhuận bình quân. Giá trị hàng hóa vì thế biểu hiện thành giá cả sản xuất."}, {"id": "src-fa343e9bc4b6-q022", "chapter": 3, "text": "Giá cả sản xuất tư bản chủ nghĩa bằng:", "options": [{"label": "A", "text": "Chi phí sản xuất cộng tỷ suất lợi nhuận bình quân."}, {"label": "B", "text": "Chi phí sản xuất cộng giá trị thặng dư"}, {"label": "C", "text": "Chi phí sản xuất cộng lợi nhuận."}, {"label": "D", "text": "Chi phí sản xuất cộng lợi nhuận bình quân"}], "answer": "D", "explanation": "Công thức giá cả sản xuất là k+p̄: chi phí sản xuất cộng số lợi nhuận bình quân. Không cộng trực tiếp một tỷ suất phần trăm vào một lượng tiền."}, {"id": "src-fa343e9bc4b6-q023", "chapter": 3, "text": "Quy luật giá cả sản xuất là:", "options": [{"label": "A", "text": "Biểu hiện của quy luật giá trị sử dụng trong giai đoạn tự do cạnh tranh của chủ nghĩa tư bản."}, {"label": "B", "text": "Biểu hiện của quy luật giá trị trong giai đoạn tự do cạnh tranh của chủ nghĩa tư bản."}, {"label": "C", "text": "Biểu hiện của quy luật giá trị trong giai đoạn độc quyền của chủ nghĩa tư bản."}, {"label": "D", "text": "Biểu hiện của quy luật cạnh tranh trong giai đoạn độc quyền của chủ nghĩa tư bản."}], "answer": "B", "explanation": "Trong tự do cạnh tranh, giá cả sản xuất hình thành trên cơ sở phân phối lại giá trị thặng dư giữa các ngành. Quy luật giá trị tiếp tục tác động thông qua hình thức biểu hiện này."}, {"id": "src-fa343e9bc4b6-q024", "chapter": 3, "text": "Tư bản thương nghiệp trong chủ nghĩa tư bản là:", "options": [{"label": "A", "text": "Một bộ phận của tư bản nông nghiệp tách ra phục vụ quá trình lưu thông hàng hóa."}, {"label": "B", "text": "Một bộ phận của tư bản công nghiệp tách ra phục vụ quá trình lưu thông hàng hóa."}, {"label": "C", "text": "Một bộ phận của tư bản cho vay tách ra phục vụ quá trình lưu thông hàng hóa."}, {"label": "D", "text": "Một bộ phận của tư bản thương nghiệp tách ra phục vụ quá trình lưu thông hàng hóa."}], "answer": "B", "explanation": "Tư bản thương nghiệp tách ra từ chức năng lưu thông hàng hóa của tư bản công nghiệp và chuyên thực hiện mua bán. Nó giúp việc tiêu thụ hàng hóa được chuyên môn hóa."}, {"id": "src-fa343e9bc4b6-q025", "chapter": 3, "text": "Nguồn gốc lợi nhuận của tư bản thương nghiệp là:", "options": [{"label": "A", "text": "Một phần lợi nhuận tạo ra trong sản xuất mà nhà tư bản công nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}, {"label": "B", "text": "Một phần giá trị thặng dư mà tư bản công nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}, {"label": "C", "text": "Một phần tỷ suất lợi nhuận tạo ra trong sản xuất mà nhà tư bản công nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}, {"label": "D", "text": "Một phần giá trị tạo ra trong nông nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}], "answer": "B", "explanation": "Hoạt động mua bán thuần túy không tự sản xuất ra giá trị thặng dư mới. Phần lợi nhuận thương nghiệp có nguồn gốc từ giá trị thặng dư mà tư bản sản xuất nhường lại cho chức năng tiêu thụ."}, {"id": "src-fa343e9bc4b6-q026", "chapter": 3, "text": "Tư bản cho vay là:", "options": [{"label": "A", "text": "Tư bản hàng hóa mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi tức."}, {"label": "B", "text": "Tư bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi tức."}, {"label": "C", "text": "Từ bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi nhuận"}, {"label": "D", "text": "Tư bản sản xuất mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi tức."}], "answer": "B", "explanation": "Người sở hữu cho người khác sử dụng một lượng tư bản tiền tệ trong thời gian thỏa thuận và thu lợi tức. Cho vay chuyển quyền sử dụng tạm thời, không chuyển hẳn quyền sở hữu vốn."}, {"id": "src-fa343e9bc4b6-q027", "chapter": 3, "text": "Nguồn gốc của lợi tức là:", "options": [{"label": "A", "text": "Một phần sản phẩm thặng dư do công nhân tạo ra trong sản xuất."}, {"label": "B", "text": "Một phần lợi nhuận do công nhân tạo ra trong sản xuất."}, {"label": "C", "text": "Một phần giá trị thặng dư do công nhân tạo ra trong sản xuất."}, {"label": "D", "text": "Một phân ngoài chi phí do công nhân tạo ra trong"}], "answer": "C", "explanation": "Người đi vay sử dụng vốn trong kinh doanh rồi chia một phần giá trị thặng dư dưới hình thức lợi tức cho người cho vay. Vì vậy nguồn gốc cuối cùng của lợi tức là giá trị thặng dư."}, {"id": "src-fa343e9bc4b6-q028", "chapter": 3, "text": "Một trong những đặc điểm cơ bản của tư bản cho vay là:", "options": [{"label": "A", "text": "Quyền sở hữu gắn liền quyền sử dụng hiệu lệnh cấm"}, {"label": "B", "text": "Quyền sở hữu tách rời quyền quản lý."}, {"label": "C", "text": "Quyền sở hữu tách rời quyền sử dụng"}, {"label": "D", "text": "Quyền quản lý tách rời quyền sử dụng."}], "answer": "C", "explanation": "Người cho vay vẫn sở hữu vốn nhưng người đi vay trực tiếp sử dụng vốn trong thời hạn vay. Đó là sự tách rời quyền sở hữu và quyền sử dụng."}, {"id": "src-fa343e9bc4b6-q029", "chapter": 3, "text": "Công thức vận động của tư bản cho vay là:", "options": [{"label": "A", "text": "H- T’"}, {"label": "B", "text": "T- T’"}, {"label": "C", "text": "T- T"}, {"label": "D", "text": "H- H’"}], "answer": "B", "explanation": "Đối với người cho vay, tiền được ứng ra rồi thu về số tiền lớn hơn: T–T′, với phần tăng là lợi tức. Các khâu sử dụng vốn của người vay bị ẩn khỏi hình thức vận động này."}, {"id": "src-fa343e9bc4b6-q030", "chapter": 3, "text": "Giới hạn của tỷ suất lợi tức (z”) là:", "options": [{"label": "A", "text": "o > z' > p'"}, {"label": "B", "text": "o <z' >p'"}, {"label": "C", "text": "o <z' <p'"}, {"label": "D", "text": "o>z' <p'"}], "answer": "C", "explanation": "Trong mô hình thông thường, lợi tức phải dương để người có vốn muốn cho vay và nhỏ hơn lợi nhuận bình quân để người vay còn lợi nhuận doanh nghiệp. Do đó 0<z′<p̄′; đây là giới hạn lý luận, không phải quy tắc bất biến của mọi giao dịch thực tế."}, {"id": "src-fa343e9bc4b6-q031", "chapter": 3, "text": "Tỷ suất lợi tức (z”) là:", "options": [{"label": "A", "text": "Tỷ lệ phần trăm giữa giá trị thặng dư và tổng số tư  bản cho vay."}, {"label": "B", "text": "Tỷ lệ phần trăm giữa lợi tức và tổng số tư bản cho vay"}, {"label": "C", "text": "Tỷ lệ phần trăm giữa lợi nhuận và tổng số tư bản cho vay."}, {"label": "D", "text": "Tỷ lệ phần trăm giữa tỷ suất lợi nhuận và tổng số tư bản cho vay."}], "answer": "B", "explanation": "z′=z/K cho vay×100%, trong đó z là số lợi tức nhận được. Mẫu số là lượng tư bản cho vay, không phải lợi nhuận hay giá trị thặng dư."}, {"id": "src-fa343e9bc4b6-q032", "chapter": 3, "text": "Địa tô tư bản là:", "options": [{"label": "A", "text": "Phần lợi nhuận ngoài lợi nhuận bình quân mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}, {"label": "B", "text": "Phần tỷ suất giá trị thặng dư ngoài lợi nhuận bình quân mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}, {"label": "C", "text": "Phần giá trị thặng dư ngoài lợi nhuận bình quân mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}, {"label": "D", "text": "Phần giá trị thặng dư ngoài lợi nhuận mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}], "answer": "C", "explanation": "Nhà tư bản nông nghiệp nhận lợi nhuận bình quân; phần thặng dư ngoài mức đó có thể được chuyển cho chủ đất dưới hình thức địa tô. Cần phân biệt địa tô với toàn bộ lợi nhuận kinh doanh nông nghiệp."}, {"id": "src-fa343e9bc4b6-q033", "chapter": 3, "text": "Các hình thức cơ bản của địa tô tư bản chủ nghĩa:", "options": [{"label": "A", "text": "Địa tô chênh lệch I; địa tô chênh lệch II."}, {"label": "B", "text": "Địa tô tuyệt đối; địa tô độc quyền"}, {"label": "C", "text": "Địa tô chênh lệch, địa tô tuyệt đối"}, {"label": "D", "text": "Địa tô chênh lệch, địa tô độc quyền"}], "answer": "C", "explanation": "Hai hình thức cơ bản là địa tô chênh lệch và địa tô tuyệt đối. Chênh lệch I và II là hai dạng thuộc địa tô chênh lệch, không phải hai nhóm cơ bản cùng cấp."}, {"id": "src-fa343e9bc4b6-q034", "chapter": 3, "text": "Địa tô tuyệt đối là địa tô mà", "options": [{"label": "A", "text": "Nhà tư bản đi thuê đất phải trả cho chủ đất, dù thuê mướn bất kỳ loại ruộng đất nào."}, {"label": "B", "text": "Nhà tư bản đi thuê đất phải trả cho chủ đất, khi thuê mướn ruộng đất tốt."}, {"label": "C", "text": "Nhà tư bản đi thuê đất không phải trả cho chủ đất, dù thuê mướn bất kỳ loại ruộng đất nào."}, {"label": "D", "text": "Nhà tư bản đi thuê đất phải trả cho chủ đất, khi thuê mướn ruộng đất xấu."}], "answer": "A", "explanation": "Địa tô tuyệt đối phải trả do quyền sở hữu ruộng đất, kể cả khi thuê loại đất xấu. Nó khác địa tô chênh lệch phụ thuộc lợi thế hoặc đầu tư thâm canh."}, {"id": "src-fa343e9bc4b6-q035", "chapter": 3, "text": "Điểm giống nhau giữa địa tô chênh lệch và địa tô tuyệt đối là:", "options": [{"label": "A", "text": "Có nguồn gốc từ giá trị thặng dư"}, {"label": "B", "text": "Tư bản bất biến."}, {"label": "C", "text": "Có nguồn gốc từ giá trị trao đổi."}, {"label": "D", "text": "Có nguồn gốc từ giá trị."}], "answer": "A", "explanation": "Cả địa tô chênh lệch và tuyệt đối đều là hình thức phân chia giá trị thặng dư trong sản xuất nông nghiệp tư bản chủ nghĩa. Chúng khác nhau về cơ chế hình thành chứ không khác nguồn gốc cuối cùng."}]};
